import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  stock: number;
  imageUrl: string;
  confidence: number; // CV recognition confidence
}

export interface Transaction {
  id: string;
  timestamp: string;
  items: { productId: string; quantity: number; price: number }[];
  total: number;
  method: 'cash' | 'card' | 'qris';
  status: 'completed' | 'pending' | 'failed';
}

export interface SalesData {
  name: string;
  sales: number;
  revenue: number;
}

export enum AdminTab {
  DASHBOARD = 'dashboard',
  INVENTORY = 'inventory',
  TRANSACTIONS = 'transactions',
  CV_MONITOR = 'cv_monitor',
  SETTINGS = 'settings'
}

import { GoogleGenAI, Type } from "@google/genai";
import { Product, Transaction } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getInventoryInsights = async (products: Product[]) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze this inventory data and provide 3 actionable insights for the business owner: ${JSON.stringify(products)}`,
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            insight: { type: Type.STRING },
            priority: { type: Type.STRING, description: 'High, Medium, Low' }
          },
          required: ['title', 'insight', 'priority']
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const generateProductDescription = async (productName: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Generate a compelling short marketing description for a retail product named: ${productName}`,
  });
  return response.text;
};

