import React, { useState, useRef, useEffect } from 'react';
import { Camera, RefreshCw, Zap, ShieldCheck, AlertTriangle } from 'lucide-react';

const CVMonitor: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [detectedItems, setDetectedItems] = useState<any[]>([]);

  useEffect(() => {
    if (isActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isActive]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setIsActive(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  // Simulated detection loop
  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => {
        const mockItems = [
          { name: 'Cola Can 330ml', confidence: (0.95 + Math.random() * 0.04).toFixed(2), x: 20, y: 30, w: 120, h: 200 },
          { name: 'Chips Packet', confidence: (0.92 + Math.random() * 0.04).toFixed(2), x: 180, y: 150, w: 220, h: 180 }
        ];
        setDetectedItems(mockItems);
      }, 500);
    } else {
      setDetectedItems([]);
    }
    return () => clearInterval(interval);
  }, [isActive]);

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">CV Real-time Monitor</h1>
          <p className="text-slate-500 text-sm">Monitor what the AI checkout camera is currently processing.</p>
        </div>
        <button 
          onClick={() => setIsActive(!isActive)}
          className={`px-6 py-2.5 rounded-xl font-bold transition-all flex items-center space-x-2 ${
            isActive 
              ? 'bg-red-50 text-red-600 border border-red-200 hover:bg-red-100' 
              : 'bg-blue-600 text-white shadow-lg shadow-blue-200 hover:bg-blue-700'
          }`}
        >
          {isActive ? (
            <>
              <RefreshCw size={20} className="animate-spin" />
              <span>Stop Monitoring</span>
            </>
          ) : (
            <>
              <Camera size={20} />
              <span>Start Live Feed</span>
            </>
          )}
        </button>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6 min-h-0">
        <div className="lg:col-span-3 bg-slate-950 rounded-2xl overflow-hidden relative shadow-2xl border-4 border-slate-900 group">
          {!isActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 space-y-4 bg-slate-900/50 backdrop-blur-sm z-10">
              <Camera size={64} strokeWidth={1} className="text-slate-700" />
              <p className="text-lg font-medium">Camera Feed Disabled</p>
              <button 
                onClick={() => setIsActive(true)}
                className="text-blue-500 hover:underline text-sm"
              >
                Connect to local workstation camera
              </button>
            </div>
          )}

          <video 
            ref={videoRef} 
            className="w-full h-full object-cover"
            playsInline
            muted
          />

          {/* CV Bounding Boxes Overlay */}
          <div className="absolute inset-0 pointer-events-none">
            {detectedItems.map((item, idx) => (
              <div 
                key={idx}
                className="absolute border-2 border-green-500 bg-green-500/10 rounded-lg animate-in zoom-in-75"
                style={{
                  left: `${item.x}px`,
                  top: `${item.y}px`,
                  width: `${item.w}px`,
                  height: `${item.h}px`
                }}
              >
                <div className="absolute -top-8 left-0 bg-green-500 text-white text-[10px] px-2 py-0.5 rounded flex items-center space-x-1 whitespace-nowrap">
                   <ShieldCheck size={12} />
                   <span className="font-bold">{item.name}</span>
                   <span className="opacity-80">{(item.confidence * 100).toFixed(0)}%</span>
                </div>
              </div>
            ))}
          </div>

          <div className="absolute top-4 left-4 flex items-center space-x-2">
            <div className={`flex items-center space-x-2 px-3 py-1.5 rounded-full backdrop-blur-md text-white text-xs font-bold border ${isActive ? 'bg-red-500/30 border-red-500/50' : 'bg-slate-500/30 border-slate-500/50'}`}>
              <div className={`w-2 h-2 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-500'}`}></div>
              <span>{isActive ? 'LIVE' : 'OFFLINE'}</span>
            </div>
            <div className="px-3 py-1.5 rounded-full bg-black/40 backdrop-blur-md text-white text-xs border border-white/10">
              CAM-01: Main Checkout
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6 flex flex-col">
          <h3 className="font-bold text-slate-800 mb-4 flex items-center">
            <Zap size={18} className="text-amber-500 mr-2" />
            Active Detections
          </h3>

          <div className="flex-1 space-y-4 overflow-y-auto">
            {detectedItems.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center p-4">
                <AlertTriangle size={32} className="text-slate-200 mb-2" />
