  Camera, 
  RefreshCw, 
  Zap, 
  AlertTriangle, 
  Layers, 
  Target, 
  Link as LinkIcon, 
  Search, 
  CheckCircle2, 
  Scan, 
  Loader2, 
  Database,
  Sparkles
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const CVMonitor: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isTraining, setIsTraining] = useState(false);
  const [selectedMapping, setSelectedMapping] = useState<any | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [detectedItems, setDetectedItems] = useState<any[]>([]);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const inventoryToMap = [
    { id: '1', name: 'Original Cola 500ml', sku: 'COF-001' },
    { id: '2', name: 'Potato Chips Spicy', sku: 'SNK-002' },
    { id: '3', name: 'Instant Noodles Beef', sku: 'FOOD-003' },
    { id: '4', name: 'Mineral Water 600ml', sku: 'DRK-004' },
    { id: '5', name: 'Susu UHT Cokelat', sku: 'MLK-005' },
  ].filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

  useEffect(() => {
    if (isActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isActive]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setIsActive(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const performAIScan = async () => {
    const base64Image = captureFrame();
    if (!base64Image) return;

    setIsScanning(true);
    setDetectedItems([]);
    setSelectedMapping(null);

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            role: 'user',
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: "Detect retail products in this image. For each object, provide a descriptive label and a 2D bounding box [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000). Return as JSON array." }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                label: { type: Type.STRING },
                box_2d: { 
                  type: Type.ARRAY, 
                  items: { type: Type.NUMBER },
                  description: "[ymin, xmin, ymax, xmax]"
                }
              },
              required: ['label', 'box_2d']
            }
          }
        }
      });

      const results = JSON.parse(response.text || '[]');
      const formattedResults = results.map((item: any, index: number) => ({
        id: `detect-${index}`,
        label: item.label,
        y: (item.box_2d[0] / 10),
        x: (item.box_2d[1] / 10),
        h: ((item.box_2d[2] - item.box_2d[0]) / 10),
        w: ((item.box_2d[3] - item.box_2d[1]) / 10)
      }));

      setDetectedItems(formattedResults);
    } catch (err) {
      console.error("AI Scan Error:", err);
      alert("Gagal melakukan scan. Pastikan API Key valid.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleMapProduct = (product: any) => {
