  const inventoryToMap = [
    { id: '1', name: 'Original Cola 500ml', sku: 'COF-001' },
    { id: '2', name: 'Potato Chips Spicy', sku: 'SNK-002' },
    { id: '3', name: 'Instant Noodles Beef', sku: 'FOOD-003' },
    { id: '4', name: 'Mineral Water 600ml', sku: 'DRK-004' },
    { id: '5', name: 'Susu UHT Cokelat', sku: 'MLK-005' },
  ].filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

  useEffect(() => {
    if (isActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isActive]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
