            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 bg-slate-900/90 backdrop-blur-md z-20">
              <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center mb-4 text-slate-600">
                <Layers size={32} />
              </div>
              <p className="text-center px-6 text-sm max-w-xs leading-relaxed">
                Hardware Kamera Siap. Tekan <b>Aktifkan Kamera</b> untuk memulai training visual.
              </p>
            </div>
          )}

          {(isScanning || isTraining) && (
            <div className="absolute inset-0 z-30 flex items-center justify-center bg-blue-600/10 backdrop-blur-[2px]">
              <div className="flex flex-col items-center space-y-3">
                 <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                 <span className="text-white text-xs font-bold tracking-widest bg-blue-600 px-3 py-1 rounded-full shadow-lg uppercase">
                   {isScanning ? 'MENDETEKSI OBJEK' : 'MENYIMPAN KE DATABASE'}
