import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  RefreshCw, 
  Zap, 
  AlertTriangle, 
  Layers, 
  Target, 
  Link as LinkIcon, 
  Search, 
  CheckCircle2, 
  Scan, 
  Loader2, 
  Database,
  Sparkles,
  Image as ImageIcon
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

interface CVMonitorProps {
  products: any[];
  setProducts: React.Dispatch<React.SetStateAction<any[]>>;
}

const CVMonitor: React.FC<CVMonitorProps> = ({ products, setProducts }) => {
  const [isActive, setIsActive] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isTraining, setIsTraining] = useState(false);
  const [selectedMapping, setSelectedMapping] = useState<any | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [detectedItems, setDetectedItems] = useState<any[]>([]);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Gunakan data dari props products (Master Data)
  const inventoryToMap = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.sku.toLowerCase().includes(searchQuery.toLowerCase())
  );

  useEffect(() => {
    if (isActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isActive]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setIsActive(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const performAIScan = async () => {
    const base64Image = captureFrame();
    if (!base64Image) return;

    setIsScanning(true);
    setDetectedItems([]);
    setSelectedMapping(null);

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            role: 'user',
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: "Detect retail products in this image. For each object, provide a descriptive label and a 2D bounding box [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000). Return as JSON array." }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                label: { type: Type.STRING },
                box_2d: { 
                  type: Type.ARRAY, 
                  items: { type: Type.NUMBER },
                  description: "[ymin, xmin, ymax, xmax]"
                }
              },
              required: ['label', 'box_2d']
            }
          }
        }
      });

      const results = JSON.parse(response.text || '[]');
      const formattedResults = results.map((item: any, index: number) => ({
        id: `detect-${index}`,
        label: item.label,
        y: (item.box_2d[0] / 10),
        x: (item.box_2d[1] / 10),
        h: ((item.box_2d[2] - item.box_2d[0]) / 10),
        w: ((item.box_2d[3] - item.box_2d[1]) / 10)
      }));

      setDetectedItems(formattedResults);
    } catch (err) {
      console.error("AI Scan Error:", err);
      alert("Gagal melakukan scan. Pastikan API Key valid.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleMapProduct = (product: any) => {
    if (!selectedMapping) return;

    // Sinkronisasi: Update visualSamples di Master Data saat dipetakan
    setProducts(prev => prev.map(p => 
      p.id === product.id ? { ...p, visualSamples: p.visualSamples + 1 } : p
    ));

    alert(`MAPPING BERHASIL!\n\nVisual: "${selectedMapping.label}"\nID Produk: "${product.name}"\n\nDataset visual produk ini telah ditambahkan.`);
    setSelectedMapping(null);
    setDetectedItems(prev => prev.filter(item => item.id !== selectedMapping.id));
  };

  const handleTrainNewVariant = async () => {
    if (!selectedMapping) return;
    setIsTraining(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 2000)); 
      alert(`TRAINING SELESAI!\nObjek "${selectedMapping.label}" telah disimpan sebagai referensi visual umum.`);
      setDetectedItems(prev => prev.filter(item => item.id !== selectedMapping.id));
      setSelectedMapping(null);
    } catch (err) {
      alert("Gagal memproses training.");
    } finally {
      setIsTraining(false);
    }
  };

  return (
    <div className="h-full flex flex-col space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Vision Mapping Engine</h1>
          <p className="text-slate-500 text-sm">Ajarkan AI untuk mengenali wajah visual produk dari database Inventory.</p>
        </div>
        <div className="flex space-x-2">
          <button 
            onClick={() => setIsActive(!isActive)}
            className={`px-5 py-2.5 rounded-xl font-bold transition-all flex items-center space-x-2 border shadow-sm ${
              isActive 
                ? 'bg-white text-slate-700 hover:bg-slate-50 border-slate-200' 
                : 'bg-blue-600 text-white border-blue-600 hover:bg-blue-700 shadow-blue-100'
            }`}
          >
            <Camera size={20} />
            <span>{isActive ? 'Stop Kamera' : 'Aktifkan Kamera'}</span>
          </button>

          {isActive && (
            <button 
              onClick={performAIScan}
              disabled={isScanning || isTraining}
              className="px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-all flex items-center space-x-2 shadow-lg disabled:opacity-50"
            >
              {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Scan size={20} />}
              <span>{isScanning ? 'Menganalisis...' : 'Scan Objek Baru'}</span>
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 min-h-0">
        <div className="lg:col-span-8 bg-slate-950 rounded-2xl overflow-hidden relative shadow-2xl border-4 border-slate-900 flex items-center justify-center">
          <canvas ref={canvasRef} className="hidden" />

          {!isActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 bg-slate-900/90 backdrop-blur-md z-20">
              <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center mb-4 text-slate-600">
                <Layers size={32} />
              </div>
              <p className="text-center px-6 text-sm max-w-xs leading-relaxed">
                Hardware Kamera Siap. Tekan <b>Aktifkan Kamera</b> untuk memulai training visual.
              </p>
            </div>
          )}

          {(isScanning || isTraining) && (
            <div className="absolute inset-0 z-30 flex items-center justify-center bg-blue-600/10 backdrop-blur-[2px]">
              <div className="flex flex-col items-center space-y-3">
                 <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                 <span className="text-white text-xs font-bold tracking-widest bg-blue-600 px-3 py-1 rounded-full shadow-lg uppercase">
                   {isScanning ? 'MENDETEKSI OBJEK' : 'MENYIMPAN KE DATABASE'}
                 </span>
              </div>
            </div>
          )}

          <video 
            ref={videoRef} 
            className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-0'}`} 
            playsInline 
            muted 
          />

          <div className="absolute inset-0 pointer-events-none overflow-hidden">
            {detectedItems.map((item) => (
              <div 
                key={item.id}
                onClick={(e) => {
                  e.stopPropagation();
                  if (!isTraining) setSelectedMapping(item);
                }}
                className={`absolute border-2 pointer-events-auto cursor-pointer transition-all hover:scale-[1.02] ${
                  selectedMapping?.id === item.id 
                    ? 'border-blue-400 bg-blue-400/20 ring-4 ring-blue-400/40' 
                    : 'border-white/60 bg-white/5 hover:bg-white/10'
                }`}
                style={{ 
                  left: `${item.x}%`, 
                  top: `${item.y}%`, 
                  width: `${item.w}%`, 
                  height: `${item.h}%`,
                  borderRadius: '4px'
                }}
              >
                <div className={`absolute -top-7 left-0 px-2 py-0.5 rounded text-[10px] font-black flex items-center space-x-1 shadow-lg backdrop-blur-md ${
                  selectedMapping?.id === item.id ? 'bg-blue-500 text-white' : 'bg-white/80 text-slate-900'
                }`}>
                   <Target size={12} className={selectedMapping?.id === item.id ? 'animate-pulse' : ''} />
                   <span className="uppercase">{item.label}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="lg:col-span-4 flex flex-col space-y-4 min-h-0">
          <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6 flex flex-col h-full overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center space-x-2">
                <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                  <LinkIcon size={18} />
                </div>
                <h3 className="font-bold text-slate-800">Hubungkan ke Produk</h3>
              </div>
            </div>

            {!selectedMapping ? (
              <div className="flex-1 flex flex-col items-center justify-center text-center p-8 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-sm mb-4">
                  <ImageIcon size={32} className="text-slate-300" />
                </div>
                <h4 className="font-bold text-slate-800 text-sm mb-1">Pilih Objek Kamera</h4>
                <p className="text-xs text-slate-500 leading-relaxed px-4">
                  Klik objek yang terdeteksi di kamera untuk menghubungkannya dengan identitas produk dari menu Inventory.
