import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  RefreshCw, 
  Zap, 
  AlertTriangle, 
  Layers, 
  Target, 
  Link as LinkIcon, 
  Search, 
  CheckCircle2, 
  Scan, 
  Loader2, 
  Database,
  Sparkles,
  Image as ImageIcon
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

interface CVMonitorProps {
  products: any[];
  setProducts: React.Dispatch<React.SetStateAction<any[]>>;
}

const CVMonitor: React.FC<CVMonitorProps> = ({ products, setProducts }) => {
  const [isActive, setIsActive] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isTraining, setIsTraining] = useState(false);
  const [selectedMapping, setSelectedMapping] = useState<any | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [detectedItems, setDetectedItems] = useState<any[]>([]);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Gunakan data dari props products (Master Data disesuaikan fieldnya)
  const inventoryToMap = products.filter(p => 
    p.nama.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  useEffect(() => {
    if (isActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isActive]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setIsActive(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const performAIScan = async () => {
    const base64Image = captureFrame();
    if (!base64Image) return;

    setIsScanning(true);
    setDetectedItems([]);
    setSelectedMapping(null);

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            role: 'user',
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: "Detect retail products in this image. For each object, provide a descriptive label and a 2D bounding box [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000). Return as JSON array." }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                label: { type: Type.STRING },
                box_2d: { 
                  type: Type.ARRAY, 
                  items: { type: Type.NUMBER },
                  description: "[ymin, xmin, ymax, xmax]"
                }
              },
              required: ['label', 'box_2d']
            }
          }
        }
      });

      const results = JSON.parse(response.text || '[]');
      const formattedResults = results.map((item: any, index: number) => ({
        id: `detect-${index}`,
        label: item.label,
        y: (item.box_2d[0] / 10),
        x: (item.box_2d[1] / 10),
        h: ((item.box_2d[2] - item.box_2d[0]) / 10),
        w: ((item.box_2d[3] - item.box_2d[1]) / 10)
      }));

      setDetectedItems(formattedResults);
    } catch (err) {
      console.error("AI Scan Error:", err);
      alert("Gagal melakukan scan. Pastikan API Key valid.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleMapProduct = (product: any) => {
    if (!selectedMapping) return;

    setProducts(prev => prev.map(p => 
      p.id === product.id ? { ...p, visualSamples: p.visualSamples + 1 } : p
    ));

    alert(`MAPPING BERHASIL!\n\nVisual: "${selectedMapping.label}"\nProduk: "${product.nama}"\n\nAI sekarang mengenali bentuk produk ini.`);
    setSelectedMapping(null);
    setDetectedItems(prev => prev.filter(item => item.id !== selectedMapping.id));
  };

  return (
    <div className="h-full flex flex-col space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Vision Mapping Engine</h1>
          <p className="text-slate-500 text-sm">Ajarkan AI untuk mengenali wajah visual produk dari database Inventory.</p>
        </div>
        <div className="flex space-x-2">
          <button onClick={() => setIsActive(!isActive)} className={`px-5 py-2.5 rounded-xl font-bold transition-all flex items-center space-x-2 border shadow-sm ${isActive ? 'bg-white text-slate-700 border-slate-200' : 'bg-blue-600 text-white border-blue-600 shadow-blue-100'}`}>
            <Camera size={20} />
            <span>{isActive ? 'Stop Kamera' : 'Aktifkan Kamera'}</span>
          </button>
          {isActive && (
            <button onClick={performAIScan} disabled={isScanning} className="px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-all flex items-center space-x-2 shadow-lg disabled:opacity-50">
              {isScanning ? <Loader2 className="animate-spin" size={20} /> : <Scan size={20} />}
              <span>{isScanning ? 'Menganalisis...' : 'Scan Objek Baru'}</span>
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 min-h-0">
        <div className="lg:col-span-8 bg-slate-950 rounded-2xl overflow-hidden relative shadow-2xl border-4 border-slate-900 flex items-center justify-center">
          {!isActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 bg-slate-900/90 backdrop-blur-md z-20">
              <Layers size={32} className="mb-4" />
              <p className="text-sm">Siap untuk training visual.</p>
            </div>
          )}
          <canvas ref={canvasRef} className="hidden" />
          <video ref={videoRef} className={`w-full h-full object-cover ${isActive ? 'opacity-100' : 'opacity-0'}`} playsInline muted />
          <div className="absolute inset-0 pointer-events-none overflow-hidden">
            {detectedItems.map((item) => (
              <div key={item.id} onClick={() => !isTraining && setSelectedMapping(item)} className={`absolute border-2 pointer-events-auto cursor-pointer transition-all ${selectedMapping?.id === item.id ? 'border-blue-400 bg-blue-400/20' : 'border-white/60 bg-white/5'}`}
                style={{ left: `${item.x}%`, top: `${item.y}%`, width: `${item.w}%`, height: `${item.h}%`, borderRadius: '4px' }}>
                <div className={`absolute -top-7 left-0 px-2 py-0.5 rounded text-[10px] font-black ${selectedMapping?.id === item.id ? 'bg-blue-500 text-white' : 'bg-white/80 text-slate-900'}`}>
                   {item.label}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="lg:col-span-4 flex flex-col space-y-4 min-h-0">
          <div className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6 flex flex-col h-full overflow-hidden">
            <h3 className="font-bold text-slate-800 flex items-center mb-6">
              <LinkIcon size={18} className="mr-2 text-blue-600" /> Hubungkan ke Produk
            </h3>

            {!selectedMapping ? (
              <div className="flex-1 flex flex-col items-center justify-center text-center p-8 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                <ImageIcon size={32} className="text-slate-300 mb-4" />
                <p className="text-xs text-slate-500">Pilih objek di kamera untuk memetakan data.</p>
              </div>
            ) : (
              <div className="flex-1 flex flex-col space-y-4 overflow-hidden animate-in slide-in-from-right-4">
