                  <p className="text-[10px] opacity-70 uppercase font-bold">Visual Terdeteksi</p>
                  <p className="text-lg font-bold">{selectedMapping.label}</p>
                </div>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
