export const STORAGE_KEY = 'vision_cashier_products';
export const API_URL_KEY = 'vision_cashier_sheet_url';

export const StorageService = {
  getSheetUrl: () => {
    return localStorage.getItem(API_URL_KEY) || '';
  },

  setSheetUrl: (url: string) => {
    localStorage.setItem(API_URL_KEY, url);
  },

  loadProducts: async (defaultProducts: any[]) => {
    const sheetUrl = StorageService.getSheetUrl();

    // Coba ambil dari Google Sheet jika ada URL
    if (sheetUrl) {
      try {
        const response = await fetch(sheetUrl);
        if (response.ok) {
          const data = await response.json();
          if (Array.isArray(data) && data.length > 0) {
            return data;
          }
        }
      } catch (e) {
        console.error("Gagal sinkronisasi dengan Google Sheets, menggunakan data lokal.", e);
      }
    }

    // Fallback ke LocalStorage
    const localData = localStorage.getItem(STORAGE_KEY);
    return localData ? JSON.parse(localData) : defaultProducts;
  },

  saveProducts: async (products: any[]) => {
    // Selalu simpan ke LocalStorage dulu
    localStorage.setItem(STORAGE_KEY, JSON.stringify(products));

    const sheetUrl = StorageService.getSheetUrl();
    if (sheetUrl) {
      try {
        await fetch(sheetUrl, {
          method: 'POST',
          mode: 'no-cors', // Apps Script membutuhkan no-cors untuk simple POST
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(products)
        });
        return true;
      } catch (e) {
        console.error("Gagal mengirim data ke Google Sheets.", e);
        return false;
      }
    }
    return true;
  }
};

