Penyebab error **"Missing catch or finally after try"** biasanya karena ada kurung kurawal `{ }` yang tidak tertutup dengan benar saat Anda menyisipkan kode baru, sehingga blok `try` kehilangan pasangannya.

Berikut adalah **seluruh kode lengkap Apps Script (Kode.gs)** yang sudah saya perbaiki strukturnya. Anda cukup menghapus semua kode lama di Apps Script dan tempel (paste) kode di bawah ini:

```javascript
/**
 * VisionPay Sync System v8.1 - FINAL ROBUST VERSION
 */

const SPREADSHEET_ID = "1PGUwYgrQFtpv2hHpr_sDAqdsp9pJFMQtGvzjn_u9LPQ";

function pastikanString(data) {
  if (data === null || data === undefined) return "";
  if (typeof data === 'object') return JSON.stringify(data);
  return data.toString();
}

function doGet(e) {
  try {
    var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    var action = e.parameter.action;

    if (action === "GET_PRODUCTS") {
      var sheet = ss.getSheetByName("Products");
      if (!sheet) return ContentService.createTextOutput(JSON.stringify([])).setMimeType(ContentService.MimeType.JSON);
      var data = sheet.getDataRange().getValues();
      var headers = data[0];
      var products = [];
      for (var i = 1; i < data.length; i++) {
        var obj = {};
        headers.forEach(function(header, index) {
          var key = header.toLowerCase().replace(/ /g, "_");
          obj[key] = data[i][index];
        });
        products.push(obj);
      }
      return ContentService.createTextOutput(JSON.stringify(products)).setMimeType(ContentService.MimeType.JSON);
    }

    if (action === "GET_MEMBER") {
      var memberId = e.parameter.id;
      var sheet = ss.getSheetByName("Members");
      if (!sheet) return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
      var data = sheet.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        if (data[i][0].toString() === memberId) {
          return ContentService.createTextOutput(JSON.stringify({
            status: "success",
            data: { id: data[i][0].toString(), name: data[i][1].toString(), tier: data[i][2].toString(), points: Number(data[i][3]) || 0 }
          })).setMimeType(ContentService.MimeType.JSON);
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "not_found" })).setMimeType(ContentService.MimeType.JSON);
    }

    return HtmlService.createHtmlOutput("VisionPay API v8.1 Online");
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    var rawData = JSON.parse(e.postData.contents);
    var action = rawData.action;

    // --- ACTION 1: SYNC_TRANSACTION (Dari Kasir) ---
    if (action === "SYNC_TRANSACTION") {
      var sheetOrders = ss.getSheetByName("Orders") || ss.insertSheet("Orders");
      var sheetDetails = ss.getSheetByName("Transaction_Details") || ss.insertSheet("Transaction_Details");
      var sheetMembers = ss.getSheetByName("Members") || ss.insertSheet("Members");

      var barisUtama = [
        new Date(),
        pastikanString(rawData.transactionId),
        pastikanString(rawData.customerType),
        pastikanString(rawData.customerName),
        pastikanString(rawData.itemsSummary),
        pastikanString(rawData.paymentMethod),
        Number(rawData.subtotal) || 0,
        pastikanString(rawData.voucherName),
        Number(rawData.voucherDiscount) || 0,
        Number(rawData.pointsDiscount) || 0,
        Number(rawData.tax) || 0,
        Number(rawData.totalPaid) || 0,
        Number(rawData.pointsEarned) || 0
      ];
      sheetOrders.appendRow(barisUtama);

      var items = rawData.items;
      if (typeof items === 'string') {
        try { items = JSON.parse(items); } catch(errItems) {}
      }

      if (items && Array.isArray(items)) {
        items.forEach(function(item) {
          sheetDetails.appendRow([
            pastikanString(rawData.transactionId), 
            pastikanString(item.name), 
            Number(item.price) || 0, 
            Number(item.qty) || 1, 
            Number(item.total) || 0,
            pastikanString(rawData.paymentMethod)
          ]);
        });
      }

      if (rawData.customerType === "MEMBER" && rawData.memberId) {
        var mRows = sheetMembers.getDataRange().getValues();
        for (var j = 1; j < mRows.length; j++) {
          if (mRows[j][0].toString() === rawData.memberId.toString()) {
            var ptsNow = Number(mRows[j][3]) || 0;
            var ptsNew = ptsNow - (Number(rawData.pointsDiscount) || 0) + (Number(rawData.pointsEarned) || 0);
            sheetMembers.getRange(j + 1, 4).setValue(ptsNew);
            break;
          }
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    } 

    // --- ACTION 2: UPDATE_PRODUCTS (Dari Admin) ---
    else if (action === "UPDATE_PRODUCTS") {
      var sheetProd = ss.getSheetByName("Products") || ss.insertSheet("Products");
      var products = rawData.products;

      sheetProd.clear();
      if (products && products.length > 0) {
        var headers = ["id", "nama", "harga", "poin", "deskripsi", "kategori", "foto", "stock", "visual_samples"];
        sheetProd.appendRow(headers);

        products.forEach(function(p) {
          sheetProd.appendRow([
            pastikanString(p.id),
            pastikanString(p.nama),
            Number(p.harga) || 0,
            Number(p.poin) || 0,
            pastikanString(p.deskripsi),
            pastikanString(p.kategori),
            pastikanString(p.foto),
            Number(p.stock) || 50,
            Number(p.visualSamples || p.visual_samples) || 0
          ]);
        });
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "Action tidak dikenal" })).setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}
```

### Cara Memasang:
1. Copy kode di atas seluruhnya.
2. Di Google Apps Script, hapus semua yang ada di `Kode.gs`.
3. Paste kode baru ini.
4. Klik ikon **Simpan** (diskette).
5. Klik **Deploy** > **New Deployment**.
6. Pilih type: **Web App**.
7. Description: **v8.1 Final**.
8. Execute as: **Me**.
