// Jika ingin URL-nya permanen, tempel URL Web App Apps Script di sini
const HARDCODED_URL = ""; 

export const StorageService = {
  getSheetUrl: () => {
    return HARDCODED_URL || localStorage.getItem(API_URL_KEY) || '';
  },

  setSheetUrl: (url: string) => {
    localStorage.setItem(API_URL_KEY, url);
  },

  testConnection: async (url: string) => {
    if (!url) return { success: false, message: "URL kosong" };
    try {
      // Tambahkan timestamp agar tidak kena cache browser
      const fetchUrl = `${url}${url.includes('?') ? '&' : '?'}action=GET_PRODUCTS&t=${Date.now()}`;
      const response = await fetch(fetchUrl);
      if (response.ok) {
        const data = await response.json();
        return { success: true, count: Array.isArray(data) ? data.length : 0 };
      }
      return { success: false, message: "Server merespon dengan error status: " + response.status };
    } catch (e) {
      return { 
        success: false, 
        message: "Gagal koneksi. Pastikan URL benar, sudah di-Deploy sebagai 'Anyone', dan internet stabil." 
      };
    }
  },

  loadProducts: async (defaultProducts: any[]) => {
    const sheetUrl = StorageService.getSheetUrl();

    if (sheetUrl) {
      try {
        const fetchUrl = `${sheetUrl}${sheetUrl.includes('?') ? '&' : '?'}action=GET_PRODUCTS&t=${Date.now()}`;
        const response = await fetch(fetchUrl);
        if (response.ok) {
          const data = await response.json();
          if (Array.isArray(data) && data.length > 0) {
            // Mapping data dari sheet ke format aplikasi
            const mappedData = data.map(p => ({
              ...p,
              id: String(p.id || ''),
              nama: String(p.nama || p.id || ''),
              harga: Number(p.harga) || 0,
              poin: Number(p.poin) || 0,
              deskripsi: String(p.deskripsi || ''),
              kategori: String(p.kategori || 'Drink'),
              foto: String(p.foto || ''),
              stock: Number(p.stock) || 0,
              visualSamples: Number(p.visual_samples || p.visualsamples || 0)
            }));

            // Simpan copy-an ke lokal buat cadangan
            localStorage.setItem(STORAGE_KEY, JSON.stringify(mappedData));
            return mappedData;
          }
        }
      } catch (e) {
        console.warn("Cloud sync gagal, menggunakan data lokal:", e);
      }
    }

    const localData = localStorage.getItem(STORAGE_KEY);
    return localData ? JSON.parse(localData) : defaultProducts;
  },

  saveProducts: async (products: any[]) => {
    // 1. Simpan ke lokal dulu biar cepat (UI tidak lag)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(products));

    const sheetUrl = StorageService.getSheetUrl();
    if (!sheetUrl) return true;

    try {
      const payload = JSON.stringify({
        action: "UPDATE_PRODUCTS",
        products: products
      });

      // TRICK: Menggunakan Blob text/plain agar tidak memicu preflight CORS yang rumit di GAS
      // Namun datanya tetap JSON yang bisa di-parse oleh Apps Script
      await fetch(sheetUrl, {
        method: 'POST',
        mode: 'no-cors', // Penting untuk Google Apps Script
        headers: {
          'Content-Type': 'text/plain', // Menghindari CORS preflight
        },
        body: payload
      });

      console.log("Data produk dikirim ke Google Sheets.");
      return true;
    } catch (e) {
      console.error("Gagal mengirim data ke Google Sheets:", e);
      return false;
    }
  }
};

