import React, { useState, useRef, useEffect } from 'react';
import { 
  Camera, 
  Target, 
  Link as LinkIcon, 
  Search, 
  CheckCircle2, 
  Scan, 
  Loader2, 
  ArrowRight,
  AlertCircle,
  Check
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

interface CVMonitorProps {
  products: any[];
  onSync: (products: any[]) => Promise<void>;
}

const CVMonitor: React.FC<CVMonitorProps> = ({ products, onSync }) => {
  const [isActive, setIsActive] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [selectedMapping, setSelectedMapping] = useState<any | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [detectedItems, setDetectedItems] = useState<any[]>([]);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const inventoryToMap = products.filter(p => {
    const s = searchQuery.toLowerCase();
    return (p.nama?.toLowerCase().includes(s)) || (p.id?.toLowerCase().includes(s));
  });

  useEffect(() => {
    if (isActive) {
      navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
        .then(stream => { if (videoRef.current) videoRef.current.srcObject = stream; })
        .catch(console.error);
    } else {
      if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
  }, [isActive]);

  const performAIScan = async () => {
    if (!videoRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
    const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    setIsScanning(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ inlineData: { mimeType: 'image/jpeg', data: base64 } }, { text: "Detect retail products. JSON format: [{label, box_2d: [y1,x1,y2,x2]}]" }] }],
        config: { responseMimeType: 'application/json' }
      });
      const results = JSON.parse(response.text || '[]');
      setDetectedItems(results.map((item: any, i: number) => ({
        id: `d-${i}`, label: item.label,
        y: (item.box_2d[0] / 10), x: (item.box_2d[1] / 10),
        h: ((item.box_2d[2] - item.box_2d[0]) / 10), w: ((item.box_2d[3] - item.box_2d[1]) / 10)
      })));
    } catch (err) { alert("Scan Gagal"); } finally { setIsScanning(false); }
  };

  const handleMapProduct = async (product: any) => {
    if (!selectedMapping) return;
    const updated = products.map(p => p.id === product.id ? { ...p, visualSamples: (p.visualSamples || 0) + 1 } : p);
    await onSync(updated);
    setSelectedMapping(null);
    setDetectedItems(prev => prev.filter(item => item.id !== selectedMapping.id));
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Vision Mapping</h1>
          <p className="text-slate-500 text-sm">Hubungkan deteksi AI ke data Google Sheets.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setIsActive(!isActive)} className={`px-4 py-2 rounded-xl font-bold border transition-all ${isActive ? 'bg-white' : 'bg-blue-600 text-white'}`}>
            <Camera size={18} className="inline mr-2" /> {isActive ? 'Stop' : 'Start'} Camera
          </button>
          {isActive && (
            <button onClick={performAIScan} disabled={isScanning} className="px-4 py-2 bg-slate-900 text-white rounded-xl font-bold disabled:opacity-50">
              {isScanning ? <Loader2 className="animate-spin inline mr-2" /> : <Scan className="inline mr-2" />} Scan
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">
        <div className="col-span-8 bg-slate-900 rounded-2xl relative overflow-hidden">
          <canvas ref={canvasRef} className="hidden" />
          <video ref={videoRef} className="w-full h-full object-cover" autoPlay playsInline muted />
          {detectedItems.map(item => (
            <div key={item.id} onClick={() => setSelectedMapping(item)} className={`absolute border-2 cursor-pointer ${selectedMapping?.id === item.id ? 'border-blue-400 bg-blue-400/20' : 'border-white/50'}`}
              style={{ left: `${item.x}%`, top: `${item.y}%`, width: `${item.w}%`, height: `${item.h}%` }}>
              <span className="absolute -top-6 left-0 bg-blue-500 text-white text-[10px] px-1 rounded">{item.label}</span>
            </div>
          ))}
        </div>
        <div className="col-span-4 bg-white rounded-2xl border p-4 flex flex-col gap-4">
           {!selectedMapping ? <p className="text-center text-slate-400 mt-20 text-xs">Pilih objek di kamera untuk memetakan produk</p> : (
             <>
               <div className="p-3 bg-blue-50 rounded-xl flex items-center justify-between">
                 <span className="text-sm font-bold">{selectedMapping.label}</span>
                 <ArrowRight size={14} />
               </div>
               <input placeholder="Search product..." className="w-full p-2 bg-slate-50 border rounded-lg text-sm" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
               <div className="flex-1 overflow-y-auto space-y-2">
                 {inventoryToMap.map(p => (
                   <button key={p.id} onClick={() => handleMapProduct(p)} className="w-full p-2 border rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
                     <img src={p.foto} className="w-8 h-8 rounded object-cover" />
                     <div className="flex-1"><p className="text-xs font-bold">{p.nama}</p><p className="text-[9px] text-slate-400">{p.id}</p></div>
                     <CheckCircle2 size={16} className={p.visualSamples > 0 ? 'text-green-500' : 'text-slate-200'} />
                   </button>
                 ))}
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};
export default CVMonitor;

