  const [newProduct, setNewProduct] = useState({ 
    id: '', 
    nama: '', 
    harga: '', 
    poin: '', 
    deskripsi: '', 
    kategori: 'Drink', 
    foto: '' 
  });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const filteredProducts = products.filter(p => 
    (p.nama?.toLowerCase().includes(searchQuery.toLowerCase())) || 
    (p.id?.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const handleGenerateDesc = async (name: string) => {
    if (!name) return;
    setLoadingAi(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a compelling short marketing description for a retail product named: ${name}`,
      });
      setNewProduct(prev => ({ ...prev, deskripsi: response.text || '' }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAi(false);
    }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    const productToAdd = {
      ...newProduct,
      id: newProduct.id.trim(),
