                <td colSpan={4} className="px-6 py-10 text-center text-slate-400">
                   Tidak ada produk ditemukan.
                </td>
              </tr>
            ) : filteredProducts.map((p) => (
              <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                <td className="px-6 py-4">
                  <div className="flex items-center space-x-3">
                    <img src={p.foto} alt="" className="w-10 h-10 rounded-lg object-cover border border-slate-100" />
                    <div>
                      <p className="font-bold text-slate-800">{p.nama}</p>
                      <p className="text-xs text-slate-400 font-mono">{p.id}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <p className="font-bold text-slate-800">Rp {p.harga.toLocaleString()}</p>
                  <p className="text-[10px] text-amber-600 font-bold flex items-center"><Star size={10} className="mr-0.5 fill-amber-600" /> {p.poin} Poin</p>
                </td>
                <td className="px-6 py-4">
                   {p.visualSamples > 0 ? (
