                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Product Name</label>
                  <input required placeholder="e.g. Cappuccino" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all" value={newProduct.nama} onChange={(e) => setNewProduct({...newProduct, nama: e.target.value})} />
                </div>
