                </label>
                <input placeholder="https://example.com/image.jpg" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all" value={newProduct.foto} onChange={(e) => setNewProduct({...newProduct, foto: e.target.value})} />
              </div>

              <div className="space-y-1">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Description</label>
                  <button type="button" onClick={() => handleGenerateDesc(newProduct.nama)} className="text-[10px] font-bold text-blue-600 flex items-center gap-1 hover:underline">
                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} Auto-AI
