import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Sparkles,
  X,
  Check,
  Star,
  CheckCircle,
  Loader2,
  Image as ImageIcon,
  Box
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface InventoryProps {
  products: any[];
  onSync: (products: any[]) => Promise<void>;
}

const Inventory: React.FC<InventoryProps> = ({ products, onSync }) => {
  const [loadingAi, setLoadingAi] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [newProduct, setNewProduct] = useState({ 
    id: '', 
    nama: '', 
    harga: '', 
    poin: '', 
    stock: '', 
    deskripsi: '', 
    kategori: 'Drink', 
    foto: '' 
  });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const filteredProducts = products.filter(p => 
    (p.nama?.toLowerCase().includes(searchQuery.toLowerCase())) || 
    (p.id?.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const handleGenerateDesc = async (name: string) => {
    if (!name) return;
    setLoadingAi(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a compelling short marketing description for a retail product named: ${name}`,
      });
      setNewProduct(prev => ({ ...prev, deskripsi: response.text || '' }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAi(false);
    }
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();

    const productData = {
      ...newProduct,
      id: newProduct.id.trim(),
      harga: parseInt(newProduct.harga as string) || 0,
      poin: parseInt(newProduct.poin as string) || 0,
      stock: parseInt(newProduct.stock as string) || 0,
      foto: newProduct.foto || `https://picsum.photos/seed/${newProduct.id || Date.now()}/100`,
      visualSamples: isEditing ? (products.find(p => p.id === newProduct.id)?.visualSamples || 0) : 0
    };

    let updatedList;
    if (isEditing) {
      updatedList = products.map(p => String(p.id).trim() === String(productData.id).trim() ? productData : p);
    } else {
      if (products.some(p => String(p.id).trim() === String(productData.id).trim())) {
        alert("ID Produk sudah ada! Gunakan ID yang berbeda.");
        return;
      }
      updatedList = [productData, ...products];
    }

    await onSync(updatedList);
    closeModal();
  };

  const openEditModal = (product: any) => {
    setNewProduct({
      id: product.id,
      nama: product.nama,
      harga: product.harga.toString(),
      poin: product.poin.toString(),
      stock: product.stock.toString(),
      deskripsi: product.deskripsi,
      kategori: product.kategori,
      foto: product.foto
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setIsEditing(false);
    setNewProduct({ id: '', nama: '', harga: '', poin: '', stock: '', deskripsi: '', kategori: 'Drink', foto: '' });
  };

  const deleteProduct = async (id: string) => {
    if(confirm(`Hapus produk "${id}" dari database?`)) {
      const cleanId = String(id).trim();
      // Filter list produk - pastikan perbandingan ID aman (trim & string)
      const updatedList = products.filter(p => String(p.id).trim() !== cleanId);

      console.log("Menghapus ID:", cleanId);
      console.log("Jumlah produk tersisa:", updatedList.length);

      await onSync(updatedList);
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Inventory Master Data</h1>
          <p className="text-slate-500 text-sm">Kelola produk yang sinkron dengan Google Sheets.</p>
        </div>
        <button onClick={() => { setIsEditing(false); setIsModalOpen(true); }} className="flex items-center justify-center space-x-2 bg-blue-600 text-white px-4 py-2.5 rounded-xl font-semibold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
          <Plus size={20} />
          <span>Tambah Produk Baru</span>
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Cari ID atau Nama Produk..." className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                <th className="px-6 py-4">Produk & ID</th>
                <th className="px-6 py-4">Harga & Poin</th>
                <th className="px-6 py-4">Stok</th>
                <th className="px-6 py-4">Status Mapping AI</th>
                <th className="px-6 py-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {filteredProducts.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-10 text-center text-slate-400">
                    Tidak ada produk ditemukan.
                  </td>
                </tr>
              ) : filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.foto} alt="" className="w-10 h-10 rounded-lg object-cover border border-slate-100" />
                      <div>
                        <p className="font-bold text-slate-800">{p.nama}</p>
                        <p className="text-xs text-slate-400 font-mono">{p.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800">Rp {Number(p.harga).toLocaleString()}</p>
                    <p className="text-[10px] text-amber-600 font-bold flex items-center"><Star size={10} className="mr-0.5 fill-amber-600" /> {p.poin} Poin</p>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className={`w-2 h-2 rounded-full ${Number(p.stock) < 10 ? 'bg-red-500' : 'bg-green-500'}`}></span>
                      <span className="font-bold text-slate-700">{p.stock} <span className="text-[10px] text-slate-400 font-normal">Pcs</span></span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    {p.visualSamples > 0 ? (
                      <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-black uppercase flex items-center w-fit">
                        <CheckCircle size={10} className="mr-1" /> Verified ({p.visualSamples})
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 bg-slate-100 text-slate-400 rounded text-[10px] font-black uppercase w-fit">Unmapped</span>
                    )}
                  </td>
