                    placeholder="e.g. COF-01" 
                    className={`w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all ${isEditing ? 'opacity-60 cursor-not-allowed' : ''}`} 
                    value={newProduct.id} 
                    onChange={(e) => setNewProduct({...newProduct, id: e.target.value})}
                    readOnly={isEditing}
