                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} Auto-AI
                  </button>
                </div>
                <textarea rows={2} placeholder="Ceritakan tentang produk ini..." className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl resize-none focus:ring-2 focus:ring-blue-500 outline-none transition-all" value={newProduct.deskripsi} onChange={(e) => setNewProduct({...newProduct, deskripsi: e.target.value})} />
              </div>

              <button type="submit" className={`w-full py-3 ${isEditing ? 'bg-blue-600' : 'bg-green-600'} text-white rounded-xl font-bold hover:opacity-90 shadow-lg flex items-center justify-center gap-2 transition-all`}>
                {isEditing ? <Check size={18} /> : <Plus size={18} />}
                {isEditing ? 'Save Changes & Sync' : 'Add Product & Sync'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
export default Inventory;

