import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Camera, 
  Settings, 
  Bell, 
  Search,
  LogOut,
  Menu,
  Layers,
  Cloud,
  CloudOff,
  RefreshCw
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import CVMonitor from './pages/CVMonitor';
import SettingsPage from './pages/Settings';

// URL API Google Apps Script
const GOOGLE_SHEET_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const SidebarLink = ({ to, icon: Icon, label, active }: { to: string, icon: any, label: string, active: boolean }) => (
  <Link 
    to={to} 
    className={`flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
      active 
        ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
        : 'text-slate-500 hover:bg-slate-100'
    }`}
  >
    <Icon size={20} />
    <span className="font-medium">{label}</span>
  </Link>
);

const App: React.FC = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [products, setProducts] = useState<any[]>([]);
  const [lastSync, setLastSync] = useState<string | null>(null);

  const loadData = async () => {
    setIsSyncing(true);
    try {
      // Tambahkan t= timestamp agar tidak kena cache browser
      const response = await fetch(`${GOOGLE_SHEET_URL}?action=GET_PRODUCTS&t=${Date.now()}`);
      if (response.ok) {
        const data = await response.json();
        if (Array.isArray(data)) {
          // Normalisasi data dari Sheet ke format yang dipahami komponen UI
          const mapped = data.map(p => ({
            id: String(p.id || '').trim(),
            nama: String(p.nama || ''),
            harga: Number(p.harga) || 0,
            poin: Number(p.poin) || 0,
            deskripsi: String(p.deskripsi || ''),
            kategori: String(p.kategori || 'Drink'),
            foto: String(p.foto || ''),
            stock: Number(p.stock) || 0,
            // Apps Script menghasilkan 'visual_samples', UI pakai 'visualSamples'
            visualSamples: Number(p.visual_samples || p.visualsamples || 0)
          }));
          setProducts(mapped);
          setLastSync(new Date().toLocaleTimeString());
          localStorage.setItem('vision_admin_cache', JSON.stringify(mapped));
        }
      }
    } catch (e) {
      console.error("Fetch Error:", e);
      const cached = localStorage.getItem('vision_admin_cache');
      if (cached) setProducts(JSON.parse(cached));
    } finally {
      setIsSyncing(false);
    }
  };

  const syncProducts = async (newProducts: any[]) => {
    // Optimistic Update: Update UI dulu supaya responsif
    setProducts(newProducts);
    setIsSyncing(true);

    try {
      const payload = {
        action: "UPDATE_PRODUCTS",
        products: newProducts
      };

      // POST ke Google Script
      await fetch(GOOGLE_SHEET_URL, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });

      setLastSync(new Date().toLocaleTimeString());
      localStorage.setItem('vision_admin_cache', JSON.stringify(newProducts));

      // Refresh setelah 2 detik untuk memastikan data benar-benar tersimpan di server
      setTimeout(() => loadData(), 2000);
    } catch (e) {
      console.error("Sync Error:", e);
      alert("Gagal sinkronisasi ke cloud.");
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <HashRouter>
      <div className="flex h-screen overflow-hidden bg-slate-50">
        <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
          <div className="flex flex-col h-full p-6">
            <div className="flex items-center space-x-3 mb-10 px-2">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-inner">
                <Camera size={24} />
              </div>
              <h1 className="text-xl font-bold tracking-tight text-slate-800">Vision<span className="text-blue-600">Admin</span></h1>
            </div>

            <nav className="flex-1 space-y-2">
              <SidebarContent />
            </nav>

            <div className="mt-auto pt-6 border-t border-slate-100 space-y-4">
              <div className="px-3 py-2 bg-slate-50 rounded-xl">
                 <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</span>
                    {isSyncing ? <RefreshCw size={12} className="text-blue-500 animate-spin" /> : <Cloud size={12} className="text-green-500" />}
                 </div>
                 <p className="text-[10px] text-slate-500 font-medium">
                   {isSyncing ? 'Syncing...' : `Last Sync: ${lastSync || 'Never'}`}
                 </p>
              </div>
              <div className="flex items-center space-x-3 p-3 rounded-xl hover:bg-red-50 text-slate-500 hover:text-red-600 transition-colors cursor-pointer">
                <LogOut size={20} />
                <span className="font-medium">Sign Out</span>
              </div>
            </div>
          </div>
        </aside>

        <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
          <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 rounded-lg hover:bg-slate-100 lg:hidden">
              <Menu size={20} />
            </button>
            <div className="flex-1 max-w-md mx-4 hidden md:block">
              <div className="text-xs font-medium text-slate-400">
                Connected: Google Sheet API v9.0
              </div>
            </div>
            <div className="flex items-center space-x-4">
              <button onClick={loadData} className="p-2 text-slate-500 hover:bg-slate-100 rounded-full" title="Refresh Data">
                <RefreshCw size={18} className={isSyncing ? 'animate-spin' : ''} />
              </button>
              <div className="h-8 w-px bg-slate-200"></div>
              <div className="flex items-center space-x-3">
                <div className="text-right hidden sm:block">
                  <p className="text-sm font-semibold text-slate-800 leading-none">Admin Utama</p>
                  <p className="text-xs text-slate-500 mt-1">Superuser</p>
                </div>
                <div className="w-10 h-10 bg-slate-200 rounded-full overflow-hidden border-2 border-white shadow-sm">
                   <img src="https://picsum.photos/seed/admin/100" alt="Avatar" />
                </div>
              </div>
            </div>
          </header>

          <div className="flex-1 overflow-y-auto p-4 lg:p-8">
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/inventory" element={<Inventory products={products} onSync={syncProducts} />} />
              <Route path="/transactions" element={<Transactions />} />
              <Route path="/mapping" element={<CVMonitor products={products} onSync={syncProducts} />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

const SidebarContent = () => {
  const location = useLocation();
  const path = location.pathname;
  return (
    <>
      <SidebarLink to="/" icon={LayoutDashboard} label="Dashboard" active={path === '/'} />
      <SidebarLink to="/inventory" icon={Package} label="Inventory" active={path === '/inventory'} />
      <SidebarLink to="/transactions" icon={History} label="Transactions" active={path === '/transactions'} />
      <SidebarLink to="/mapping" icon={Layers} label="Mapping Produk" active={path === '/mapping'} />
      <SidebarLink to="/settings" icon={Settings} label="Settings" active={path === '/settings'} />
    </>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Sparkles,
  X,
  Check,
  Star,
  CheckCircle,
  Loader2,
  Image as ImageIcon,
  Box
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface InventoryProps {
  products: any[];
  onSync: (products: any[]) => Promise<void>;
}

const Inventory: React.FC<InventoryProps> = ({ products, onSync }) => {
  const [loadingAi, setLoadingAi] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [newProduct, setNewProduct] = useState({ 
    id: '', 
    nama: '', 
    harga: '', 
    poin: '', 
    stock: '', 
    deskripsi: '', 
    kategori: 'Drink', 
    foto: '' 
  });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Gunakan filter yang aman
  const filteredProducts = products.filter(p => 
    (p.nama?.toLowerCase().includes(searchQuery.toLowerCase())) || 
    (p.id?.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const handleGenerateDesc = async (name: string) => {
    if (!name) return;
    setLoadingAi(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a compelling short marketing description for a retail product named: ${name}`,
      });
      setNewProduct(prev => ({ ...prev, deskripsi: response.text || '' }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAi(false);
    }
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();

    // Pastikan data bersih sebelum dikirim ke Sync
    const productData = {
      id: newProduct.id.trim(),
      nama: newProduct.nama.trim(),
      harga: Number(newProduct.harga) || 0,
      poin: Number(newProduct.poin) || 0,
      stock: Number(newProduct.stock) || 0,
      deskripsi: newProduct.deskripsi,
      kategori: newProduct.kategori,
      foto: newProduct.foto || `https://picsum.photos/seed/${newProduct.id}/100`,
      visualSamples: isEditing ? (products.find(p => p.id === newProduct.id)?.visualSamples || 0) : 0
    };

    let updatedList;
    if (isEditing) {
      updatedList = products.map(p => String(p.id).trim() === String(productData.id).trim() ? productData : p);
    } else {
      if (products.some(p => String(p.id).trim() === String(productData.id).trim())) {
        alert("ID Produk sudah ada!");
        return;
      }
      updatedList = [productData, ...products];
    }

    await onSync(updatedList);
    closeModal();
  };

  const openEditModal = (product: any) => {
    setNewProduct({
      id: String(product.id),
      nama: String(product.nama),
      harga: String(product.harga),
      poin: String(product.poin),
      stock: String(product.stock),
      deskripsi: String(product.deskripsi),
      kategori: String(product.kategori),
      foto: String(product.foto)
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setIsEditing(false);
    setNewProduct({ id: '', nama: '', harga: '', poin: '', stock: '', deskripsi: '', kategori: 'Drink', foto: '' });
  };

  const deleteProduct = async (id: string) => {
    if(confirm(`Yakin ingin menghapus produk "${id}"?`)) {
      const cleanId = String(id).trim();
      const updatedList = products.filter(p => String(p.id).trim() !== cleanId);
      await onSync(updatedList);
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Inventory Master Data</h1>
          <p className="text-slate-500 text-sm">Kelola produk yang tersinkron otomatis ke Cloud.</p>
        </div>
        <button onClick={() => { setIsEditing(false); setIsModalOpen(true); }} className="flex items-center justify-center space-x-2 bg-blue-600 text-white px-4 py-2.5 rounded-xl font-semibold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
          <Plus size={20} />
          <span>Tambah Produk</span>
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Cari ID atau Nama Produk..." className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase">Total: {filteredProducts.length} Produk</div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                <th className="px-6 py-4">Produk</th>
                <th className="px-6 py-4">Harga & Poin</th>
                <th className="px-6 py-4">Stok</th>
                <th className="px-6 py-4">AI Scan</th>
                <th className="px-6 py-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {filteredProducts.length === 0 ? (
                <tr><td colSpan={5} className="px-6 py-10 text-center text-slate-400 italic">Data kosong atau sedang memuat...</td></tr>
              ) : filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.foto} alt="" className="w-10 h-10 rounded-lg object-cover border border-slate-100" />
                      <div>
                        <p className="font-bold text-slate-800">{p.nama}</p>
                        <p className="text-[10px] text-slate-400 font-mono">{p.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800">Rp {Number(p.harga).toLocaleString()}</p>
                    <p className="text-[10px] text-amber-600 font-bold flex items-center"><Star size={10} className="mr-0.5 fill-amber-600" /> {p.poin} Pts</p>
                  </td>
                  <td className="px-6 py-4 font-bold text-slate-700">{p.stock} <span className="text-[10px] text-slate-400 font-normal">Pcs</span></td>
                  <td className="px-6 py-4">
                    {p.visualSamples > 0 ? (
                      <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-black flex items-center w-fit">
                        <CheckCircle size={10} className="mr-1" /> OK ({p.visualSamples})
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 bg-slate-100 text-slate-400 rounded text-[10px] font-black w-fit uppercase">No Map</span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-2">
                      <button onClick={() => openEditModal(p)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><Edit3 size={16} /></button>
                      <button onClick={() => deleteProduct(p.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden">
            <div className="px-6 py-5 border-b flex items-center justify-between bg-slate-50">
              <h3 className="font-bold text-slate-800">{isEditing ? 'Edit Produk' : 'Tambah Produk'}</h3>
              <button onClick={closeModal} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Product ID</label>
                  <input required disabled={isEditing} className={`w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none ${isEditing ? 'opacity-50' : ''}`} value={newProduct.id} onChange={(e) => setNewProduct({...newProduct, id: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Nama Produk</label>
                  <input required className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.nama} onChange={(e) => setNewProduct({...newProduct, nama: e.target.value})} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Harga</label>
                  <input required type="number" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.harga} onChange={(e) => setNewProduct({...newProduct, harga: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Poin Reward</label>
                  <input required type="number" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.poin} onChange={(e) => setNewProduct({...newProduct, poin: e.target.value})} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Stok</label>
                  <input required type="number" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.stock} onChange={(e) => setNewProduct({...newProduct, stock: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Kategori</label>
                  <select className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.kategori} onChange={(e) => setNewProduct({...newProduct, kategori: e.target.value})}>
                    <option value="Drink">Drink</option><option value="Food">Food</option><option value="Snack">Snack</option>
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">URL Foto</label>
                <input className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={newProduct.foto} onChange={(e) => setNewProduct({...newProduct, foto: e.target.value})} />
              </div>
              <div className="space-y-1">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Deskripsi</label>
                  <button type="button" onClick={() => handleGenerateDesc(newProduct.nama)} className="text-[10px] font-bold text-blue-600 flex items-center gap-1">
                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} AI-Desc
                  </button>
                </div>
                <textarea rows={2} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl resize-none outline-none" value={newProduct.deskripsi} onChange={(e) => setNewProduct({...newProduct, deskripsi: e.target.value})} />
              </div>
              <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 flex items-center justify-center gap-2">
                <Check size={18} /> Simpan ke Cloud
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
export default Inventory;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Camera, 
  Settings, 
  Bell, 
  Search,
  LogOut,
  Menu,
  Layers,
  Cloud,
  CloudOff,
  RefreshCw,
  AlertCircle
} from 'lucide-center';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import CVMonitor from './pages/CVMonitor';
import SettingsPage from './pages/Settings';

// PASTIKAN URL INI ADALAH URL "WEB APP" ANDA DARI GOOGLE APPS SCRIPT
const GOOGLE_SHEET_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const App: React.FC = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [products, setProducts] = useState<any[]>([]);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loadData = async () => {
    setIsSyncing(true);
    setError(null);
    try {
      console.log("Memulai pengambilan data dari:", GOOGLE_SHEET_URL);
      const response = await fetch(`${GOOGLE_SHEET_URL}?action=GET_PRODUCTS&t=${Date.now()}`);

      if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

      const data = await response.json();
      console.log("Raw Data dari Sheet:", data);

      if (data && data.status === "error") {
        throw new Error(data.message || "Gagal mengambil data dari Spreadsheet");
      }

      if (Array.isArray(data)) {
        // Normalisasi data: Memastikan nama properti sesuai meskipun di Sheet ada spasi atau huruf besar
        const mapped = data.map((item: any) => {
          // Cari kunci secara dinamis untuk menghindari masalah case-sensitive
          const findKey = (name: string) => {
            const keys = Object.keys(item);
            return keys.find(k => k.toLowerCase().trim() === name.toLowerCase()) || '';
          };

          return {
            id: String(item[findKey('id')] || '').trim(),
            nama: String(item[findKey('nama')] || item[findKey('id')] || ''),
            harga: Number(item[findKey('harga')]) || 0,
            poin: Number(item[findKey('poin')]) || 0,
            deskripsi: String(item[findKey('deskripsi')] || ''),
            kategori: String(item[findKey('kategori')] || 'Drink'),
            foto: String(item[findKey('foto')] || ''),
            stock: Number(item[findKey('stock')]) || 0,
            visualSamples: Number(item[findKey('visual_samples')] || item[findKey('visualsamples')] || 0)
          };
        }).filter(p => p.id !== ""); // Buang baris kosong jika ada

        console.log("Mapped Products:", mapped);
        setProducts(mapped);
        setLastSync(new Date().toLocaleTimeString());
        localStorage.setItem('vision_admin_cache', JSON.stringify(mapped));
      } else {
