import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import CVMonitor from './pages/CVMonitor';
import SettingsPage from './pages/Settings';

// URL API Google Apps Script - Pastikan ID ini sesuai dengan deployment terbaru Anda
const GOOGLE_SHEET_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const SidebarNav = () => {
  const location = useLocation();
  const path = location.pathname;

  const SidebarLink = ({ to, icon: Icon, label, active }: { to: string, icon: any, label: string, active: boolean }) => (
    <Link 
      to={to} 
      className={`flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
        active 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
          : 'text-slate-500 hover:bg-slate-100'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </Link>
  );

  return (
    <nav className="flex-1 space-y-2">
      <SidebarLink to="/" icon={LayoutDashboard} label="Dashboard" active={path === '/'} />
      <SidebarLink to="/inventory" icon={Package} label="Inventory" active={path === '/inventory'} />
      <SidebarLink to="/transactions" icon={History} label="Transactions" active={path === '/transactions'} />
      <SidebarLink to="/mapping" icon={Layers} label="Mapping Produk" active={path === '/mapping'} />
      <SidebarLink to="/settings" icon={Settings} label="Settings" active={path === '/settings'} />
    </nav>
  );
};

const App: React.FC = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [products, setProducts] = useState<any[]>([]);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loadData = async () => {
    setIsSyncing(true);
    setError(null);
    try {
      // Menambahkan timeout agar tidak gantung jika koneksi buruk
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 10000);

      const response = await fetch(`${GOOGLE_SHEET_URL}?action=GET_PRODUCTS&t=${Date.now()}`, {
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) throw new Error(`HTTP ${response.status}: Koneksi Gagal`);

      const data = await response.json();

      if (Array.isArray(data)) {
        const mapped = data.map((item: any) => {
          const k = (name: string) => Object.keys(item).find(key => key.toLowerCase().trim() === name.toLowerCase()) || '';
          return {
            id: String(item[k('id')] || '').trim(),
            nama: String(item[k('nama')] || item[k('id')] || 'Unnamed'),
            harga: Number(item[k('harga')]) || 0,
            poin: Number(item[k('poin')]) || 0,
            deskripsi: String(item[k('deskripsi')] || ''),
            kategori: String(item[k('kategori')] || 'Drink'),
            foto: String(item[k('foto')] || `https://picsum.photos/seed/${item[k('id')]}/100`),
            stock: Number(item[k('stock')]) || 0,
            visualSamples: Number(item[k('visual_samples')] || item[k('visualsamples')] || 0)
          };
        }).filter(p => p.id !== "");

        setProducts(mapped);
        setLastSync(new Date().toLocaleTimeString());
        localStorage.setItem('vision_admin_cache', JSON.stringify(mapped));
      } else {
        throw new Error("Format data Cloud tidak valid.");
      }
    } catch (e: any) {
      console.error("Fetch Error:", e);
      let errorMsg = "Gagal terhubung ke Cloud.";
      if (e.name === 'AbortError') errorMsg = "Koneksi Timeout (Terlalu Lambat).";
      else if (e.message.includes('Failed to fetch')) errorMsg = "CORS Error atau Link Script Salah.";

      setError(errorMsg);
      const cached = localStorage.getItem('vision_admin_cache');
      if (cached) setProducts(JSON.parse(cached));
    } finally {
      setIsSyncing(false);
    }
  };

  const syncProducts = async (newProducts: any[]) => {
    setProducts(newProducts);
    setIsSyncing(true);
    setError(null);
    try {
      await fetch(GOOGLE_SHEET_URL, {
        method: 'POST',
        mode: 'no-cors', // Penting untuk Google Apps Script
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: "UPDATE_PRODUCTS", products: newProducts })
      });

      setLastSync(new Date().toLocaleTimeString());
      localStorage.setItem('vision_admin_cache', JSON.stringify(newProducts));
      setTimeout(() => loadData(), 2000);
    } catch (e: any) {
      setError("Gagal menyimpan ke Cloud.");
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <HashRouter>
      <div className="flex h-screen overflow-hidden bg-slate-50">
        <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 ease-in-out lg:relative lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
          <div className="flex flex-col h-full p-6">
            <div className="flex items-center space-x-3 mb-10 px-2">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-inner">
                <Camera size={24} />
              </div>
              <h1 className="text-xl font-bold tracking-tight text-slate-800">Vision<span className="text-blue-600">Admin</span></h1>
            </div>

            <SidebarNav />

            <div className="mt-auto pt-6 border-t border-slate-100 space-y-4">
              {error && (
                <div className="group relative">
                  <div className="px-3 py-2 bg-red-50 text-red-600 rounded-xl flex items-center gap-2 text-[10px] font-bold cursor-help">
                    <AlertCircle size={14} /> <span>{error}</span>
                  </div>
                  <div className="absolute bottom-full left-0 mb-2 w-48 p-2 bg-slate-800 text-white text-[9px] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                    Pastikan Apps Script sudah di-deploy sebagai "Web App" & "Anyone".
                  </div>
                </div>
              )}
              <div className="px-3 py-2 bg-slate-50 rounded-xl">
                 <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</span>
                    {isSyncing ? <RefreshCw size={12} className="text-blue-500 animate-spin" /> : <Cloud size={12} className={error ? "text-red-400" : "text-green-500"} />}
                 </div>
                 <p className="text-[10px] text-slate-500 font-medium">
                   {isSyncing ? 'Syncing...' : `Last Sync: ${lastSync || 'Never'}`}
                 </p>
              </div>
              <div className="flex items-center space-x-3 p-3 rounded-xl hover:bg-red-50 text-slate-500 hover:text-red-600 transition-colors cursor-pointer">
                <LogOut size={20} />
                <span className="font-medium">Sign Out</span>
              </div>
            </div>
          </div>
        </aside>

        <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
          <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 rounded-lg hover:bg-slate-100 lg:hidden">
              <Menu size={20} />
            </button>
            <div className="flex-1 max-w-md mx-4 hidden md:block">
              <div className="text-xs font-mono text-slate-400 opacity-50 uppercase tracking-tighter flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${error ? 'bg-red-500' : 'bg-green-500'}`}></div>
                System {error ? 'Offline / Error' : 'Online'}
              </div>
            </div>
            <div className="flex items-center space-x-4">
              <button onClick={loadData} disabled={isSyncing} className="p-2 text-slate-500 hover:bg-slate-100 rounded-full transition-colors disabled:opacity-30">
                <RefreshCw size={18} className={isSyncing ? 'animate-spin' : ''} />
              </button>
              <div className="h-8 w-px bg-slate-200"></div>
              <div className="flex items-center space-x-3">
                <div className="text-right hidden sm:block">
                  <p className="text-sm font-semibold text-slate-800 leading-none">Admin Utama</p>
                  <p className="text-xs text-slate-500 mt-1">Superuser</p>
                </div>
                <div className="w-10 h-10 bg-slate-200 rounded-full overflow-hidden border-2 border-white shadow-sm hover:scale-105 transition-transform cursor-pointer">
                   <img src="https://picsum.photos/seed/admin/100" alt="Avatar" />
                </div>
              </div>
            </div>
          </header>

          <div className="flex-1 overflow-y-auto p-4 lg:p-8">
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/inventory" element={<Inventory products={products} onSync={syncProducts} />} />
              <Route path="/transactions" element={<Transactions />} />
              <Route path="/mapping" element={<CVMonitor products={products} onSync={syncProducts} />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

