### 2. Cara Memperbaiki Backend (Google Apps Script)
Pesan "Failed to fetch" biasanya karena skrip Anda tidak mengizinkan akses luar. Pastikan kode di Apps Script Anda seperti ini:

```javascript
// KODE UNTUK GOOGLE APPS SCRIPT (Extensions > Apps Script)

function doGet(e) {
  var action = e.parameter.action;
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Products"); // Pastikan nama sheet sesuai

  if (action == 'GET_PRODUCTS') {
    var data = sheet.getDataRange().getValues();
    var headers = data[0];
    var result = [];
    for (var i = 1; i < data.length; i++) {
      var obj = {};
      for (var j = 0; j < headers.length; j++) {
        var key = headers[j].toString().toLowerCase().trim();
        obj[key] = data[i][j];
      }
      result.push(obj);
    }
    // WAJIB: Gunakan ContentService untuk menghindari CORS error
    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  var params = JSON.parse(e.postData.contents);
  var action = params.action;
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Products");

  if (action == 'UPDATE_PRODUCTS') {
    sheet.clear();
    var products = params.products;
    if (products.length > 0) {
      var headers = Object.keys(products[0]);
      sheet.appendRow(headers);
      products.forEach(function(p) {
        var row = headers.map(function(h) { return p[h]; });
        sheet.appendRow(row);
      });
    }
    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  }
}
```

### Langkah Penting untuk Deploy:
1. Di Editor Apps Script, klik tombol **Deploy** (biru) di kanan atas.
2. Pilih **New Deployment**.
3. Pilih type: **Web App**.
4. Description: "v1 stable".
5. Execute as: **Me** (Email Anda).
6. Who has access: **Anyone** (Ini kunci agar "Failed to fetch" hilang).
7. Klik **Deploy**, lalu copy **Web App URL** dan paste ke variabel `GOOGLE_SHEET_URL` di `App.tsx`.

Aplikasi sekarang akan menampilkan pesan error yang lebih jelas jika koneksi terputus dan akan tetap bisa menampilkan data lama (dari cache) jika fetch gagal.

