                  <label className="text-[10px] font-bold text-slate-400 uppercase">Deskripsi</label>
                  <button type="button" onClick={() => handleGenerateDesc(newProduct.nama)} className="text-[10px] font-bold text-blue-600 flex items-center gap-1">
                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} AI-Desc
                  </button>
                </div>
                <textarea rows={2} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl resize-none outline-none" value={newProduct.deskripsi} onChange={(e) => setNewProduct({...newProduct, deskripsi: e.target.value})} />
              </div>
              <button 
                type="submit" 
                disabled={isSaving}
                className={`w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 flex items-center justify-center gap-2 transition-all ${isSaving ? 'opacity-70 cursor-not-allowed scale-[0.98]' : ''}`}
              >
                {isSaving ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    Menyimpan ke Cloud...
                  </>
                ) : (
                  <>
                    <Check size={18} /> Simpan ke Cloud
                  </>
                )}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
export default Inventory;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Camera, 
  Settings, 
  Bell, 
