Agar produk yang Anda kelola di halaman **Admin** ini bisa langsung dikenali dan di-scan di **Project Frontend (Kasir)**, Anda perlu melakukan sinkronisasi data di sisi Kasir menggunakan URL Google Apps Script yang sama.

Berikut adalah langkah-langkah teknis dan potongan kode yang perlu Anda terapkan pada **Project Frontend Kasir** Anda:

### 1. Hubungkan Database di Project Kasir
Buka file utama di project kasir Anda (misal `App.tsx` atau `Cashier.tsx`), lalu tambahkan fungsi fetch untuk mengambil data dari Google Sheet yang sama.

```typescript
// Di Project Kasir Anda
const GOOGLE_SHEET_URL = "URL_APPS_SCRIPT_YANG_SAMA_DENGAN_ADMIN";

const [inventory, setInventory] = useState([]);

const syncWithCloud = async () => {
  try {
    const response = await fetch(`${GOOGLE_SHEET_URL}?action=GET_PRODUCTS`);
    const data = await response.json();
    setInventory(data); // Sekarang kasir punya data produk terbaru dari admin
  } catch (e) {
    console.error("Gagal sinkron data cloud");
  }
};

useEffect(() => { syncWithCloud(); }, []);
```

### 2. Berikan "Konteks" ke AI Gemini saat Scanning
Ini adalah bagian terpenting. Agar AI tidak menebak-nebak nama produk secara umum, Anda harus memberikan daftar produk Anda ke dalam prompt Gemini di sisi Kasir.

Ubah bagian pemanggilan Gemini di project Kasir Anda menjadi seperti ini:

```typescript
// Contoh implementasi di sisi Kasir saat klik tombol "Scan"
const performScan = async (imageBuffer) => {
  // Buat daftar nama produk agar AI tahu apa yang dicari
  const productContext = inventory.map(p => `- ${p.nama} (ID: ${p.id})`).join('\n');

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: imageBuffer } },
          { text: `Identifikasi produk retail dalam gambar ini. 
                   HANYA pilih dari daftar produk resmi berikut:
                   ${productContext}

                   Kembalikan dalam format JSON: [{id, nama, quantity}]` }
        ]
      }
    ],
    config: { responseMimeType: 'application/json' }
  });

  const results = JSON.parse(response.text);
  // Hasil scan sekarang akan menggunakan ID dan Nama yang sama persis dengan Admin!
};
```

### 3. Kenapa Ini Berhasil?
1.  **Satu Sumber Kebenaran (Single Source of Truth)**: Admin mengubah harga/stok di Google Sheet $\rightarrow$ Kasir mengambil data terbaru $\rightarrow$ AI Gemini dipandu untuk hanya mengenali produk yang ada di daftar tersebut.
2.  **Mapping Visual**: Jika Anda sudah mengisi `visualSamples` di halaman Admin (melalui menu Mapping), AI akan jauh lebih akurat karena data tersebut tersimpan di database dan bisa dikirim sebagai instruksi tambahan ke model.

---

### Pembaruan pada Admin App
Untuk memudahkan Anda memantau status koneksi ini, saya akan menambahkan informasi **"Client API Key"** di halaman Settings Admin agar Anda bisa menyalinnya dengan mudah ke project kasir.

import React, { useState, useCallback } from 'react';
import { ViewState, CartItem, Voucher } from './types';
import LandingPage from './components/LandingPage';
import VisionPOS from './components/VisionPOS';
import SelectInputPage from './components/SelectInputPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [pointsUsed, setPointsUsed] = useState<number>(0);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);
  const [currentTransactionId, setCurrentTransactionId] = useState<string>("");

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishVisionScan = (items: CartItem[]) => {
    setCart(items);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_MEMBER&id=${id}`);
      const result = await response.json();

      if (result.status === "success") {
        setMemberInfo(result.data);
        setIsMember(true);
        setView(ViewState.SELECT_VOUCHER);
      } else {
        alert("Member tidak ditemukan di database.");
      }
    } catch (error) {
      console.error("Member search error:", error);
      alert("Gagal menghubungi server database member.");
    } finally {
      setIsCheckingMember(false);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' ? subtotal * (selectedVoucher.value / 100) : selectedVoucher.value;
  };

  const prepareTransaction = () => {
    const newId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;
    setCurrentTransactionId(newId);
    setView(ViewState.PAYMENT_QRIS);
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, method: string = "QRIS") => {
    if (cart.length === 0 || isSyncing) return;

    setIsSyncing(true);
    setView(ViewState.SUCCESS); // Langsung pindah ke halaman sukses untuk UX yang cepat

    const itemsSummary = cart.map(item => `${item.name} (${item.quantity}x)`).join(', ');
    const totalPointsEarned = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
    const itemsDetail = cart.map(item => ({ 
      name: item.name, 
      price: item.price, 
      qty: item.quantity, 
      total: item.price * item.quantity 
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId: currentTransactionId,
      memberId: memberInfo?.id || "",
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary,
      items: JSON.stringify(itemsDetail), // Pastikan dalam bentuk string JSON agar tidak pecah
      subtotal,
      voucherName: selectedVoucher?.title || "-",
      voucherDiscount: discount,
      pointsDiscount: pointsUsed,
      tax,
      totalPaid: total,
      pointsEarned: totalPointsEarned,
      paymentMethod: method
    };

    try {
      // Mengirim dengan POST namun isi body tetap stringified JSON
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      // Tunggu hanya 300ms untuk efek visual "Syncing" di SuccessPage
      setTimeout(() => {
        setIsSyncing(false);
      }, 300);
    }
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item).filter(item => item.quantity > 0));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const totalBeforeTax = Math.max(0, subtotal - voucherDiscount - pointsUsed);
    const tax = totalBeforeTax * 0.11;
    const finalTotal = totalBeforeTax + tax;

    switch (view) {
      case ViewState.LANDING: 
        return <LandingPage onStart={handleStart} />;

      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.POS)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;

      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={() => setView(ViewState.CART)} />;

      case ViewState.POS: 
        return <VisionPOS onBack={() => setView(ViewState.SELECT_INPUT)} onCheckout={handleFinishVisionScan} />;

      case ViewState.CART: 
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsUsed={pointsUsed} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => setView(ViewState.LANDING)} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={prepareTransaction} />;

      case ViewState.MEMBERSHIP_SCAN: 
        return <MembershipPage isChecking={isCheckingMember} onSkip={() => setView(ViewState.SELECT_VOUCHER)} onDetected={() => handleFindMember()} />;

      case ViewState.SELECT_VOUCHER: 
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} selectedVoucherId={selectedVoucher?.id} pointsUsed={pointsUsed} onSelectPoints={setPointsUsed} onSelect={setSelectedVoucher} onBack={() => setView(ViewState.CART)} cart={cart} />;

      case ViewState.PAYMENT_QRIS: 
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, "QRIS")} total={finalTotal} />;

      case ViewState.SUCCESS: 
        return <SuccessPage transactionId={currentTransactionId} onFinish={() => { setCart([]); setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setPointsUsed(0); setCurrentTransactionId(""); }} total={finalTotal} isSyncing={isSyncing} />;

      default: 
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.POS, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS, ViewState.SCANNING_BARCODE].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

