import React, { useRef, useState, useEffect } from 'react';
import { Camera, RefreshCw, ChevronLeft, Scan, ShoppingCart, Loader2, Sparkles, AlertCircle } from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { CartItem } from '../types';

interface VisionPOSProps {
  inventory: any[]; // Data inventory dikirim dari App.tsx
  onBack: () => void;
  onCheckout: (items: CartItem[]) => void;
}

const VisionPOS: React.FC<VisionPOSProps> = ({ inventory, onBack, onCheckout }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraReady, setIsCameraReady] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, []);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = s;
        setStream(s);
        setIsCameraReady(true);
      }
    } catch (err) {
      console.error("Camera error:", err);
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
  };

  const handleScan = async () => {
    if (!videoRef.current || !canvasRef.current || isScanning) return;

    setIsScanning(true);
    const canvas = canvasRef.current;
    const video = videoRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(video, 0, 0);
    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      // 2. Buat daftar produk yang dikenali (Daftar ini berasal dari Admin)
      const productKnowledge = inventory.map(p => `- ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}`).join('\n');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            role: 'user',
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Tugas: Identifikasi produk retail dalam gambar ini.
                       HANYA pilih produk yang ada dalam daftar resmi di bawah ini:

                       ${productKnowledge}

                       Format jawaban harus JSON: 
                       [{"id": "string", "name": "string", "quantity": number, "price": number}]

                       Jika produk tidak ada di daftar resmi, jangan masukkan ke hasil.` }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          temperature: 0.1, // Rendah agar lebih presisi
        }
      });

      const detected = JSON.parse(response.text || '[]');

      // Map hasil deteksi ke format CartItem kasir
      const cartItems: CartItem[] = detected.map((item: any) => ({
        id: item.id,
        name: item.name,
        price: item.price,
        quantity: item.quantity,
        points: inventory.find(inv => inv.id === item.id)?.poin || 0,
        imageUrl: inventory.find(inv => inv.id === item.id)?.foto || ""
      }));

      if (cartItems.length > 0) {
        onCheckout(cartItems);
      } else {
        alert("Tidak ada produk yang dikenali dari inventory resmi.");
      }
    } catch (err) {
      console.error("Scan error:", err);
      alert("Gagal melakukan scan. Pastikan pencahayaan cukup.");
    } finally {
      setIsScanning(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black flex flex-col z-[100]">
      <div className="absolute top-0 inset-x-0 p-4 flex items-center justify-between z-10 bg-gradient-to-b from-black/70 to-transparent">
        <button onClick={onBack} className="p-3 bg-white/10 backdrop-blur-md rounded-2xl text-white">
          <ChevronLeft size={24} />
        </button>
        <div className="flex flex-col items-center">
           <span className="text-white text-sm font-black uppercase tracking-[0.2em]">Vision Mode</span>
           <span className="text-white/60 text-[10px] flex items-center gap-1">
             <Sparkles size={10} className="text-blue-400" /> Powered by Gemini 3 Flash
           </span>
        </div>
        <button onClick={() => window.location.reload()} className="p-3 bg-white/10 backdrop-blur-md rounded-2xl text-white">
          <RefreshCw size={20} />
        </button>
      </div>

      <div className="flex-1 relative overflow-hidden flex items-center justify-center">
        {!isCameraReady && (
          <div className="flex flex-col items-center text-white space-y-4">
            <Loader2 className="animate-spin text-blue-500" size={40} />
            <p className="text-sm font-medium opacity-50">Initializing Camera...</p>
          </div>
        )}
        <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
        <canvas ref={canvasRef} className="hidden" />

        {/* Overlay Scanner UI */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
           <div className="w-72 h-72 border-2 border-white/20 rounded-[40px] relative">
              <div className="absolute -top-1 -left-1 w-12 h-12 border-t-4 border-l-4 border-blue-500 rounded-tl-3xl"></div>
              <div className="absolute -top-1 -right-1 w-12 h-12 border-t-4 border-r-4 border-blue-500 rounded-tr-3xl"></div>
              <div className="absolute -bottom-1 -left-1 w-12 h-12 border-b-4 border-l-4 border-blue-500 rounded-bl-3xl"></div>
              <div className="absolute -bottom-1 -right-1 w-12 h-12 border-b-4 border-r-4 border-blue-500 rounded-br-3xl"></div>

              {isScanning && (
                <div className="absolute inset-0 bg-blue-500/20 animate-pulse rounded-[40px] flex items-center justify-center">
                   <div className="bg-white/90 backdrop-blur-md px-4 py-2 rounded-full flex items-center gap-2">
                     <Loader2 size={16} className="animate-spin text-blue-600" />
                     <span className="text-xs font-black text-blue-600 uppercase">Analyzing...</span>
                   </div>
                </div>
              )}
           </div>
        </div>

        <div className="absolute top-1/2 left-4 right-4 -translate-y-1/2 flex flex-col items-center gap-4 pointer-events-none opacity-40">
           <div className="w-full h-[1px] bg-blue-400 animate-[scan_2s_infinite]"></div>
        </div>
      </div>

      <div className="p-8 bg-black/80 backdrop-blur-xl border-t border-white/10 flex flex-col items-center gap-6">
        <div className="flex items-center gap-2 px-4 py-2 bg-blue-500/10 rounded-full border border-blue-500/20">
          <AlertCircle size={14} className="text-blue-400" />
          <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest text-center">
            Posisikan {inventory.length} produk resmi Anda di dalam kotak
          </p>
        </div>

        <button 
          onClick={handleScan}
          disabled={isScanning || !isCameraReady}
          className={`group relative flex flex-col items-center justify-center w-24 h-24 rounded-full transition-all duration-300 ${isScanning ? 'bg-slate-800 scale-90' : 'bg-white hover:scale-110 active:scale-95 shadow-[0_0_30px_rgba(255,255,255,0.3)]'}`}
        >
          <div className={`p-4 rounded-full transition-colors ${isScanning ? 'text-slate-600' : 'text-black'}`}>
            <Scan size={32} />
          </div>
