import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Sparkles,
  X,
  Check,
  Star,
  CheckCircle,
  Loader2
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface InventoryProps {
  products: any[];
  onSync: (products: any[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ products, onSync }) => {
  const [loadingAi, setLoadingAi] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [newProduct, setNewProduct] = useState({ 
    id: '', 
    nama: '', 
    harga: '', 
    poin: '', 
    stock: '', 
    deskripsi: '', 
    kategori: 'Drink', 
    foto: '' 
  });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const filteredProducts = products.filter(p => 
    p.nama.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.id.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleGenerateDesc = async (name: string) => {
    if (!name) return;
    setLoadingAi(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Buat deskripsi singkat pemasaran untuk produk retail bernama: ${name}`,
      });
      setNewProduct(prev => ({ ...prev, deskripsi: response.text || '' }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAi(false);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    const productData = {
      ...newProduct,
      harga: Number(newProduct.harga),
      poin: Number(newProduct.poin),
      stock: Number(newProduct.stock),
      visualSamples: isEditing ? (products.find(p => p.id === newProduct.id)?.visualSamples || 0) : 0
    };

    let updatedList;
    if (isEditing) {
      updatedList = products.map(p => p.id === productData.id ? productData : p);
    } else {
      updatedList = [productData, ...products];
    }

    setTimeout(() => {
      onSync(updatedList);
      setIsSaving(false);
      setIsModalOpen(false);
      setNewProduct({ id: '', nama: '', harga: '', poin: '', stock: '', deskripsi: '', kategori: 'Drink', foto: '' });
    }, 400);
  };

  const openEditModal = (product: any) => {
    setNewProduct(product);
    setIsEditing(true);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Inventory Management</h1>
          <p className="text-slate-500 text-sm">Kelola katalog produk dan data visual pengenalan AI.</p>
        </div>
        <button onClick={() => { setIsEditing(false); setIsModalOpen(true); }} className="flex items-center justify-center space-x-2 bg-blue-600 text-white px-4 py-2.5 rounded-xl font-semibold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
          <Plus size={20} />
          <span>Tambah Produk Baru</span>
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Cari ID atau Nama Produk..." className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest px-4">Total: {filteredProducts.length} Produk</div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                <th className="px-6 py-4">Produk</th>
                <th className="px-6 py-4">Harga & Poin</th>
                <th className="px-6 py-4">Stok Tersedia</th>
                <th className="px-6 py-4">Visual Data</th>
                <th className="px-6 py-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.foto || 'https://images.unsplash.com/photo-1553413077-190dd305871c?w=100'} alt="" className="w-10 h-10 rounded-lg object-cover border" />
                      <div>
                        <p className="font-bold text-slate-800">{p.nama}</p>
                        <p className="text-[10px] text-slate-400 font-mono uppercase">{p.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800">Rp {p.harga.toLocaleString()}</p>
                    <p className="text-[10px] text-amber-600 font-bold flex items-center"><Star size={10} className="mr-0.5 fill-amber-600" /> {p.poin} Pts</p>
                  </td>
                  <td className="px-6 py-4 font-bold text-slate-700">{p.stock} <span className="text-[10px] text-slate-400 font-normal">Pcs</span></td>
                  <td className="px-6 py-4">
                    {p.visualSamples > 0 ? (
                      <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-black flex items-center w-fit">
                        <CheckCircle size={10} className="mr-1" /> Ready ({p.visualSamples})
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 bg-slate-100 text-slate-400 rounded text-[10px] font-black w-fit uppercase tracking-tighter">No Mapping</span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-2">
                      <button onClick={() => openEditModal(p)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit3 size={16} /></button>
                      <button className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden">
            <div className="px-6 py-5 border-b flex items-center justify-between bg-slate-50">
              <h3 className="font-bold text-slate-800">{isEditing ? 'Update Product' : 'Add New Product'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full"><X size={20} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ID</label>
                  <input required disabled={isEditing} className="w-full px-4 py-2 bg-slate-50 border rounded-xl outline-none" value={newProduct.id} onChange={(e) => setNewProduct({...newProduct, id: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Name</label>
                  <input required className="w-full px-4 py-2 bg-slate-50 border rounded-xl outline-none" value={newProduct.nama} onChange={(e) => setNewProduct({...newProduct, nama: e.target.value})} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Price (Rp)</label>
                  <input required type="number" className="w-full px-4 py-2 bg-slate-50 border rounded-xl outline-none" value={newProduct.harga} onChange={(e) => setNewProduct({...newProduct, harga: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Stock</label>
                  <input required type="number" className="w-full px-4 py-2 bg-slate-50 border rounded-xl outline-none" value={newProduct.stock} onChange={(e) => setNewProduct({...newProduct, stock: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Description</label>
                  <button type="button" onClick={() => handleGenerateDesc(newProduct.nama)} className="text-[10px] font-bold text-blue-600 flex items-center gap-1">
                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} Generate AI
                  </button>
                </div>
                <textarea rows={2} className="w-full px-4 py-2 bg-slate-50 border rounded-xl resize-none outline-none" value={newProduct.deskripsi} onChange={(e) => setNewProduct({...newProduct, deskripsi: e.target.value})} />
              </div>
              <button 
                type="submit" 
                disabled={isSaving}
                className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 flex items-center justify-center gap-2"
              >
                {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Check size={18} />}
                {isEditing ? 'Simpan Perubahan' : 'Tambah Ke Katalog'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
export default Inventory;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Settings as SettingsIcon, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Target,
  Cloud
} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

// TEMPELKAN URL WEB APP APPS SCRIPT ANDA DI SINI
const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwIQCNctYcqmOjYhyc7rjOQy6Yjm__B4hHRlPH0iNUUw3ikM1bSFP5KyERLAYW-ljwBZw/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Load data dari Google Sheets saat pertama kali dibuka
  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const data = await response.json();
      if (Array.isArray(data)) {
        setProducts(data);
      }
    } catch (error) {
      console.error("Gagal mengambil data dari Google Sheets:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    // Update state lokal dulu supaya cepat (Optimistic Update)
    setProducts(updatedProducts);

    // Kirim ke Cloud Apps Script
    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors', // Penting untuk Apps Script POST
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({
          action: 'UPDATE_INVENTORY',
          products: updatedProducts
        })
      });
      console.log("Cloud Sync Success");
    } catch (error) {
      console.error("Cloud Sync Failed:", error);
      alert("Gagal sinkronisasi ke Google Sheets.");
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-400 font-medium animate-pulse">Menghubungkan ke Cloud Inventory...</p>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings />;
      default: return <Dashboard />;
    }
  };

  const NavItem = ({ tab, icon: Icon, label }: { tab: AdminTab, icon: any, label: string }) => (
    <button
      onClick={() => setActiveTab(tab)}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
        activeTab === tab 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 translate-x-1' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
      }`}
    >
      <Icon size={20} />
      <span className="font-semibold text-sm">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      {/* Sidebar */}
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Target size={20} />
            </div>
