import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  Edit3, 
  Trash2, 
  Sparkles,
  X,
  Check,
  Star,
  CheckCircle,
  Loader2,
  Image as ImageIcon,
  Tag
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface InventoryProps {
  products: any[];
  onSync: (products: any[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ products, onSync }) => {
  const [loadingAi, setLoadingAi] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [newProduct, setNewProduct] = useState({ 
    id: '', 
    nama: '', 
    harga: '', 
    poin: '', 
    deskripsi: '', 
    kategori: 'Drink', 
    foto: '',
    stock: ''
  });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const filteredProducts = products.filter(p => 
    (p.nama?.toLowerCase() || '').includes(searchQuery.toLowerCase()) || 
    (p.id?.toLowerCase() || '').includes(searchQuery.toLowerCase())
  );

  const handleGenerateDesc = async (name: string) => {
    if (!name) return;
    setLoadingAi(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Buat deskripsi singkat pemasaran untuk produk retail bernama: ${name}. Gunakan bahasa Indonesia yang menarik.`,
      });
      setNewProduct(prev => ({ ...prev, deskripsi: response.text || '' }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAi(false);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    const productData = {
      ...newProduct,
      harga: Number(newProduct.harga),
      poin: Number(newProduct.poin),
      stock: Number(newProduct.stock),
      visualSamples: isEditing ? (products.find(p => p.id === newProduct.id)?.visualSamples || 0) : 0
    };

    let updatedList;
    if (isEditing) {
      updatedList = products.map(p => p.id === productData.id ? productData : p);
    } else {
      updatedList = [productData, ...products];
    }

    // Simulasi delay penyimpanan
    setTimeout(() => {
      onSync(updatedList);
      setIsSaving(false);
      setIsModalOpen(false);
      setNewProduct({ id: '', nama: '', harga: '', poin: '', deskripsi: '', kategori: 'Drink', foto: '', stock: '' });
    }, 400);
  };

  const openEditModal = (product: any) => {
    setNewProduct({
      id: product.id || '',
      nama: product.nama || '',
      harga: String(product.harga || ''),
      poin: String(product.poin || ''),
      deskripsi: product.deskripsi || '',
      kategori: product.kategori || 'Drink',
      foto: product.foto || '',
      stock: String(product.stock || '')
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Inventory Management</h1>
          <p className="text-slate-500 text-sm">Kelola katalog produk sesuai database Google Sheet Anda.</p>
        </div>
        <button onClick={() => { 
          setIsEditing(false); 
          setNewProduct({ id: '', nama: '', harga: '', poin: '', deskripsi: '', kategori: 'Drink', foto: '', stock: '' });
          setIsModalOpen(true); 
        }} className="flex items-center justify-center space-x-2 bg-blue-600 text-white px-4 py-2.5 rounded-xl font-semibold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
          <Plus size={20} />
          <span>Tambah Produk Baru</span>
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Cari ID atau Nama Produk..." className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest px-4">Total: {filteredProducts.length} Produk</div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                <th className="px-6 py-4">Produk</th>
                <th className="px-6 py-4">Kategori</th>
                <th className="px-6 py-4">Harga & Poin</th>
                <th className="px-6 py-4">Stok</th>
                <th className="px-6 py-4">Visual Data</th>
                <th className="px-6 py-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.foto || 'https://images.unsplash.com/photo-1553413077-190dd305871c?w=100'} alt="" className="w-10 h-10 rounded-lg object-cover border" />
                      <div>
                        <p className="font-bold text-slate-800">{p.nama}</p>
                        <p className="text-[10px] text-slate-400 font-mono uppercase">{p.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded-md text-[10px] font-bold uppercase">{p.kategori}</span>
                  </td>
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800">Rp {Number(p.harga).toLocaleString()}</p>
                    <p className="text-[10px] text-amber-600 font-bold flex items-center"><Star size={10} className="mr-0.5 fill-amber-600" /> {p.poin} Pts</p>
                  </td>
                  <td className="px-6 py-4 font-bold text-slate-700">{p.stock} <span className="text-[10px] text-slate-400 font-normal">Pcs</span></td>
                  <td className="px-6 py-4">
                    {p.visualSamples > 0 ? (
                      <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded text-[10px] font-black flex items-center w-fit">
                        <CheckCircle size={10} className="mr-1" /> Ready ({p.visualSamples})
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 bg-slate-100 text-slate-400 rounded text-[10px] font-black w-fit uppercase tracking-tighter">No Mapping</span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-2">
                      <button onClick={() => openEditModal(p)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit3 size={16} /></button>
                      <button className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
            <div className="px-6 py-5 border-b flex items-center justify-between bg-slate-50 shrink-0">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center">
                  <Plus size={20} />
                </div>
                <div>
                  <h3 className="font-bold text-slate-800">{isEditing ? 'Update Product' : 'Add New Product'}</h3>
                  <p className="text-[10px] text-slate-500 font-medium">Lengkapi semua kolom database produk</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveProduct} className="p-6 space-y-5 overflow-y-auto">
              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    ID Produk <span className="text-red-500">*</span>
                  </label>
                  <input required disabled={isEditing} placeholder="Contoh: TC-001" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.id} onChange={(e) => setNewProduct({...newProduct, id: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    Nama Produk <span className="text-red-500">*</span>
                  </label>
                  <input required placeholder="Nama barang" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.nama} onChange={(e) => setNewProduct({...newProduct, nama: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-5">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    Kategori <Tag size={10} />
                  </label>
                  <select className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm appearance-none" value={newProduct.kategori} onChange={(e) => setNewProduct({...newProduct, kategori: e.target.value})}>
                    <option value="Drink">Drink</option>
                    <option value="Food">Food</option>
                    <option value="Snack">Snack</option>
                    <option value="Daily">Daily</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    URL Foto <ImageIcon size={10} />
                  </label>
                  <input placeholder="https://link-foto.com/gambar.jpg" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.foto} onChange={(e) => setNewProduct({...newProduct, foto: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-3 gap-5">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    Harga (Rp) <span className="text-red-500">*</span>
                  </label>
                  <input required type="number" placeholder="5000" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.harga} onChange={(e) => setNewProduct({...newProduct, harga: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    Poin Loyalty
                  </label>
                  <input type="number" placeholder="5" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.poin} onChange={(e) => setNewProduct({...newProduct, poin: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                    Stok (Pcs) <span className="text-red-500">*</span>
                  </label>
                  <input required type="number" placeholder="10" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.stock} onChange={(e) => setNewProduct({...newProduct, stock: e.target.value})} />
                </div>
              </div>

              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Deskripsi Produk</label>
                  <button type="button" onClick={() => handleGenerateDesc(newProduct.nama)} className="text-[10px] font-bold text-blue-600 flex items-center gap-1 hover:text-blue-700 transition-colors">
                    {loadingAi ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />} Generate Deskripsi AI
                  </button>
                </div>
                <textarea rows={3} placeholder="Penjelasan singkat produk..." className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl resize-none outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm" value={newProduct.deskripsi} onChange={(e) => setNewProduct({...newProduct, deskripsi: e.target.value})} />
              </div>

              <div className="pt-2">
                <button 
                  type="submit" 
                  disabled={isSaving}
                  className="w-full py-3.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 flex items-center justify-center gap-2 transition-all active:scale-[0.98] disabled:opacity-70"
                >
                  {isSaving ? <Loader2 size={20} className="animate-spin" /> : <Check size={20} />}
                  {isEditing ? 'Simpan Perubahan Produk' : 'Tambahkan ke Katalog Cloud'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
