                  <select className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-sm appearance-none" value={newProduct.kategori} onChange={(e) => setNewProduct({...newProduct, kategori: e.target.value})}>
                    <option value="Drink">Drink</option>
                    <option value="Food">Food</option>
