import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Settings as SettingsIcon, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Target,
  Cloud,
  RefreshCw
} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

const DEFAULT_URL = "https://script.google.com/macros/s/AKfycbwIQCNctYcqmOjYhyc7rjOQy6Yjm__B4hHRlPH0iNUUw3ikM1bSFP5KyERLAYW-ljwBZw/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  // Ambil URL dari localStorage jika ada, jika tidak pakai DEFAULT_URL
  const [scriptUrl, setScriptUrl] = useState(() => {
    return localStorage.getItem('vision_script_url') || DEFAULT_URL;
  });

  // Load data dari Google Sheets saat pertama kali dibuka
  useEffect(() => {
    fetchInventory();
  }, [scriptUrl]);

  const fetchInventory = async () => {
    if (!scriptUrl || scriptUrl.includes('...')) return;
    try {
      setIsLoading(true);
      const response = await fetch(`${scriptUrl}?action=GET_PRODUCTS`);
      const data = await response.json();
      if (Array.isArray(data)) {
        setProducts(data);
      }
    } catch (error) {
      console.error("Gagal mengambil data dari Google Sheets:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setIsSyncing(true);
    setProducts(updatedProducts); // Update UI lokal (Optimistic)

    try {
      // Gunakan format x-www-form-urlencoded untuk menghindari masalah CORS di Apps Script
      // Data dikirim dalam parameter 'payload'
      const params = new URLSearchParams();
      params.append('action', 'UPDATE_INVENTORY');
      params.append('payload', JSON.stringify(updatedProducts));

      // Kirim POST ke Apps Script
      // Apps Script akan menerima ini di e.parameter.payload dalam fungsi doPost(e)
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 
          'Content-Type': 'application/x-www-form-urlencoded' 
        },
        body: params.toString()
      });

      console.log("Data berhasil dikirim ke Cloud Sync");
      return true;
    } catch (error) {
      console.error("Cloud Sync Failed:", error);
      alert("Gagal sinkronisasi. Cek koneksi internet atau validitas URL Apps Script.");
      return false;
    } finally {
      setTimeout(() => setIsSyncing(false), 1500);
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-400 font-medium animate-pulse">Menghubungkan ke Cloud Inventory...</p>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings onUrlUpdate={(url) => setScriptUrl(url)} />;
      default: return <Dashboard />;
    }
  };

  const NavItem = ({ tab, icon: Icon, label }: { tab: AdminTab, icon: any, label: string }) => (
    <button
      onClick={() => setActiveTab(tab)}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
        activeTab === tab 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 translate-x-1' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
      }`}
    >
      <Icon size={20} />
      <span className="font-semibold text-sm">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Target size={20} />
            </div>
            <span className="font-bold text-xl tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem tab={AdminTab.DASHBOARD} icon={LayoutDashboard} label="Dashboard" />
          <NavItem tab={AdminTab.INVENTORY} icon={Package} label="Inventory" />
          <NavItem tab={AdminTab.MAPPING} icon={Target} label="AI Mapping" />
          <NavItem tab={AdminTab.TRANSACTIONS} icon={History} label="Transactions" />
          <div className="pt-4 mt-4 border-t border-slate-100">
             <NavItem tab={AdminTab.SETTINGS} icon={SettingsIcon} label="Settings" />
          </div>
        </nav>

        <div className="px-6 py-4">
          <div className={`flex items-center space-x-2 text-[10px] font-black uppercase tracking-widest ${isSyncing ? 'text-blue-500' : 'text-green-500'}`}>
            {isSyncing ? <RefreshCw size={12} className="animate-spin" /> : <Cloud size={12} />}
            {isSidebarOpen && <span>{isSyncing ? 'Syncing to Sheet...' : 'Cloud Connected'}</span>}
          </div>
        </div>

        <div className="p-4 border-t border-slate-100">
          <button className="w-full flex items-center space-x-3 px-4 py-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors">
            <LogOut size={20} />
            {isSidebarOpen && <span className="font-semibold text-sm">Sign Out</span>}
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <div className="relative w-96 max-w-md hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search data..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            />
          </div>

          <div className="flex items-center space-x-4">
            <button onClick={fetchInventory} title="Refresh Cloud Data" className="p-2 text-slate-400 hover:bg-slate-50 rounded-full transition-colors">
              <RefreshCw size={20} className={isLoading ? 'animate-spin text-blue-500' : ''} />
            </button>
            <button className="p-2 text-slate-400 hover:bg-slate-50 rounded-full relative">
              <Bell size={20} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="h-8 w-[1px] bg-slate-100"></div>
            <div className="flex items-center space-x-3 pl-2">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-900">Administrator</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Store Manager</p>
              </div>
              <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center text-white font-bold shadow-lg shadow-blue-100">
                A
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
