### Penting: Periksa Apps Script Anda
Untuk memastikan data tersimpan, kode **`doPost(e)`** di Google Apps Script Anda harus bisa membaca parameter `payload`. Berikut adalah contoh struktur Apps Script yang kompatibel dengan kode di atas:

```javascript
function doPost(e) {
  // Ambil data dari parameter 'payload' yang dikirim frontend
  var action = e.parameter.action;
  var payload = e.parameter.payload;

  if (action === "UPDATE_INVENTORY" && payload) {
    var products = JSON.parse(payload);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName("Sheet1"); // Ganti sesuai nama sheet Anda

    // Hapus data lama (kecuali header)
    if (sheet.getLastRow() > 1) {
      sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).clearContent();
    }

    // Siapkan baris baru sesuai urutan di screenshot: id, nama, harga, poin, deskripsi, kategori, foto, stock
    var rows = products.map(function(p) {
      return [p.id, p.nama, p.harga, p.poin, p.deskripsi, p.kategori, p.foto, p.stock];
    });

    // Masukkan data baru
    if (rows.length > 0) {
      sheet.getRange(2, 1, rows.length, 8).setValues(rows);
    }

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  }
}
