import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Settings as SettingsIcon, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Target,
  Cloud,
  RefreshCw,
  AlertCircle
} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

const DEFAULT_URL = "https://script.google.com/macros/s/AKfycby5qNoLXSDVndwvxRDH1Qo4oI2mAuXJ7EVP7mKVdOMGVcUiBfLgyrr_z6Ad6NxF92PN4A/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [scriptUrl, setScriptUrl] = useState(() => {
    return localStorage.getItem('vision_script_url') || DEFAULT_URL;
  });

  useEffect(() => {
    fetchAllData();
  }, [scriptUrl]);

  const fetchAllData = async () => {
    if (!scriptUrl || scriptUrl.includes('...')) {
      setIsLoading(false);
      setError("URL Apps Script belum dikonfigurasi dengan benar.");
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      // Ambil Produk & Transaksi secara paralel
      const [prodRes, transRes] = await Promise.all([
        fetch(`${scriptUrl}?action=GET_PRODUCTS`),
        fetch(`${scriptUrl}?action=GET_TRANSACTIONS`)
      ]);

      if (!prodRes.ok || !transRes.ok) throw new Error("Gagal menghubungi server Cloud.");

      const prodData = await prodRes.json();
      const transData = await transRes.json();

      setProducts(Array.isArray(prodData) ? prodData : []);
      setTransactions(Array.isArray(transData) ? transData : []);

    } catch (error: any) {
      console.error("Fetch Error:", error);
      setError(error.message || "Gagal mengambil data dari Google Sheets.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setIsSyncing(true);
    setProducts(updatedProducts);

    try {
      const payload = {
        action: 'UPDATE_PRODUCTS',
        products: updatedProducts
      };

      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });

      return true;
    } catch (error) {
      console.error("Sync Failed:", error);
      return false;
    } finally {
      setTimeout(() => setIsSyncing(false), 1000);
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 font-medium animate-pulse">Sinkronisasi Cloud...</p>
        </div>
      );
    }

    if (error && activeTab !== AdminTab.SETTINGS) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-4">
          <div className="p-4 bg-red-50 text-red-600 rounded-full">
            <AlertCircle size={40} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-900">Koneksi Cloud Terputus</h3>
            <p className="text-slate-500 max-w-sm mx-auto">{error}</p>
          </div>
          <button 
            onClick={() => setActiveTab(AdminTab.SETTINGS)}
            className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-all"
          >
            Buka Pengaturan URL
          </button>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard transactions={transactions} />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions transactions={transactions} onRefresh={fetchAllData} />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings onUrlUpdate={(url) => setScriptUrl(url)} />;
      default: return <Dashboard transactions={transactions} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Target size={20} />
            </div>
            <span className="font-bold text-xl tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {[
            { id: AdminTab.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
            { id: AdminTab.INVENTORY, icon: Package, label: 'Inventory' },
            { id: AdminTab.MAPPING, icon: Target, label: 'AI Mapping' },
            { id: AdminTab.TRANSACTIONS, icon: History, label: 'Transactions' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === item.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <item.icon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">{item.label}</span>}
            </button>
          ))}
          <div className="pt-4 mt-4 border-t border-slate-100">
             <button
              onClick={() => setActiveTab(AdminTab.SETTINGS)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === AdminTab.SETTINGS 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <SettingsIcon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">Settings</span>}
            </button>
          </div>
        </nav>

        <div className="px-6 py-4">
          <div className={`flex items-center space-x-2 text-[10px] font-black uppercase tracking-widest ${isSyncing ? 'text-blue-500' : 'text-green-500'}`}>
            {isSyncing ? <RefreshCw size={12} className="animate-spin" /> : <Cloud size={12} />}
            {isSidebarOpen && <span>{isSyncing ? 'Syncing...' : 'Connected'}</span>}
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <h2 className="font-bold text-slate-400 uppercase text-[10px] tracking-[0.2em]">Management Console</h2>
          <div className="flex items-center space-x-4">
            <button onClick={fetchAllData} className="p-2 text-slate-400 hover:bg-slate-50 rounded-full transition-colors">
              <RefreshCw size={20} className={isLoading ? 'animate-spin' : ''} />
            </button>
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white font-bold">A</div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 bg-[#F8FAFC]">
          <div className="max-w-7xl mx-auto h-full">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
