} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

const DEFAULT_URL = "https://script.google.com/macros/s/AKfycby5qNoLXSDVndwvxRDH1Qo4oI2mAuXJ7EVP7mKVdOMGVcUiBfLgyrr_z6Ad6NxF92PN4A/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string | null>(null);

  const [scriptUrl, setScriptUrl] = useState(() => {
    return localStorage.getItem('vision_script_url') || DEFAULT_URL;
  });

  useEffect(() => {
    fetchAllData();
  }, [scriptUrl]);

  const fetchWithTimeout = async (url: string, options = {}, timeout = 10000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(id);
      return response;
    } catch (e) {
      clearTimeout(id);
      throw e;
    }
  };

  const fetchAllData = async () => {
    if (!scriptUrl || scriptUrl.includes('...')) {
      setIsLoading(false);
      setError("URL Apps Script belum dikonfigurasi.");
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      setDebugInfo(null);

      // Ambil data secara terpisah agar satu kegagalan tidak merusak semuanya
      const results = await Promise.allSettled([
        fetchWithTimeout(`${scriptUrl}?action=GET_PRODUCTS`),
        fetchWithTimeout(`${scriptUrl}?action=GET_TRANSACTIONS`)
      ]);

      // Handle Products
      if (results[0].status === 'fulfilled') {
        const res = results[0].value;
        if (res.ok) {
          try {
            const data = await res.json();
            setProducts(Array.isArray(data) ? data : []);
          } catch (e) {
            console.error("Products JSON parse failed");
            setDebugInfo(prev => (prev || "") + " [Products: Invalid JSON]");
          }
        } else {
          setDebugInfo(prev => (prev || "") + " [Products: 404/500]");
        }
      } else {
        setDebugInfo(prev => (prev || "") + " [Products: Connection Refused]");
      }

      // Handle Transactions
      if (results[1].status === 'fulfilled') {
        const res = results[1].value;
        if (res.ok) {
          try {
            const data = await res.json();
            setTransactions(Array.isArray(data) ? data : []);
          } catch (e) {
            console.error("Transactions JSON parse failed");
            setDebugInfo(prev => (prev || "") + " [Transactions: Invalid JSON]");
          }
        } else {
          setDebugInfo(prev => (prev || "") + " [Transactions: Not Found]");
        }
      } else {
        setDebugInfo(prev => (prev || "") + " [Transactions: Network Error]");
      }

      // Jika keduanya gagal total baru set error utama
      if (results[0].status === 'rejected' && results[1].status === 'rejected') {
        throw new Error("Gagal terhubung ke Apps Script. Pastikan URL benar dan sudah di-publish ke 'Anyone'.");
      }

    } catch (error: any) {
      console.error("Global Fetch Error:", error);
      setError(error.message || "Terjadi kesalahan koneksi.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setIsSyncing(true);
    setProducts(updatedProducts);

    try {
      const payload = {
        action: 'UPDATE_PRODUCTS',
        products: updatedProducts
      };

      // POST ke Apps Script butuh mode no-cors jika skrip tidak menghandle OPTIONS
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });

      return true;
    } catch (error) {
      console.error("Sync Failed:", error);
      return false;
    } finally {
      setTimeout(() => setIsSyncing(false), 1000);
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 font-medium animate-pulse">Menghubungkan ke Cloud...</p>
        </div>
      );
    }

    if (error && activeTab !== AdminTab.SETTINGS) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-6 animate-in zoom-in-95">
          <div className="p-6 bg-red-50 text-red-600 rounded-3xl">
            <WifiOff size={48} />
          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold text-slate-900">Oops! Cloud Terputus</h3>
            <p className="text-slate-500 max-w-sm mx-auto leading-relaxed">{error}</p>
            {debugInfo && (
              <div className="mt-4 p-3 bg-slate-100 rounded-xl font-mono text-[10px] text-slate-500">
                Debug: {debugInfo}
              </div>
            )}
          </div>
          <div className="flex gap-3">
            <button onClick={fetchAllData} className="px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-black transition-all">
              Coba Lagi
            </button>
            <button 
              onClick={() => setActiveTab(AdminTab.SETTINGS)}
              className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100"
            >
              Cek URL Skrip
            </button>
          </div>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard transactions={transactions} />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions transactions={transactions} onRefresh={fetchAllData} />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings onUrlUpdate={(url) => setScriptUrl(url)} />;
      default: return <Dashboard transactions={transactions} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col shadow-sm`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-md">
              <Target size={20} />
            </div>
            <span className="font-bold text-xl tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400 transition-colors">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {[
            { id: AdminTab.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
            { id: AdminTab.INVENTORY, icon: Package, label: 'Inventory' },
            { id: AdminTab.MAPPING, icon: Target, label: 'AI Mapping' },
            { id: AdminTab.TRANSACTIONS, icon: History, label: 'Transactions' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === item.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <item.icon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">{item.label}</span>}
            </button>
          ))}
          <div className="pt-4 mt-4 border-t border-slate-100">
             <button
              onClick={() => setActiveTab(AdminTab.SETTINGS)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === AdminTab.SETTINGS 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
