            {error ? <AlertCircle size={12} /> : isSyncing ? <RefreshCw size={12} className="animate-spin" /> : <Cloud size={12} />}
            {isSidebarOpen && <span>{error ? 'Offline' : isSyncing ? 'Syncing...' : 'Cloud Active'}</span>}
          </div>
          {isSidebarOpen && debugInfo && !error && (
            <p className="text-[8px] text-slate-400 mt-1 truncate">{debugInfo}</p>
