const DEFAULT_URL = "https://script.google.com/macros/s/AKfycby5qNoLXSDVndwvxRDH1Qo4oI2mAuXJ7EVP7mKVdOMGVcUiBfLgyrr_z6Ad6NxF92PN4A/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string | null>(null);

  const [scriptUrl, setScriptUrl] = useState(() => {
    return localStorage.getItem('vision_script_url') || DEFAULT_URL;
  });

  useEffect(() => {
    fetchAllData();
  }, [scriptUrl]);

  const normalizeKeys = (arr: any[]) => {
    if (!Array.isArray(arr)) return [];
    return arr.map(item => {
      const normalized: any = {};
      Object.keys(item).forEach(key => {
        // Ubah "ID Transaksi" atau "id_transaksi" jadi standar
        const k = key.toLowerCase().replace(/_/g, ' ').trim();
        normalized[k] = item[key];
      });
      return normalized;
    });
  };

  const fetchWithTimeout = async (url: string, options = {}, timeout = 10000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(id);
      return response;
    } catch (e) {
      clearTimeout(id);
      throw e;
    }
  };

  const fetchAllData = async () => {
    if (!scriptUrl || scriptUrl.includes('...')) {
      setIsLoading(false);
      setError("URL Apps Script belum dikonfigurasi.");
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      setDebugInfo(null);

      const results = await Promise.allSettled([
        fetchWithTimeout(`${scriptUrl}?action=GET_PRODUCTS`),
        fetchWithTimeout(`${scriptUrl}?action=GET_TRANSACTIONS`)
      ]);

      // Handle Products
      if (results[0].status === 'fulfilled') {
        const res = results[0].value;
        if (res.ok) {
          try {
            const data = await res.json();
            setProducts(normalizeKeys(Array.isArray(data) ? data : []));
          } catch (e) {
            setDebugInfo(prev => (prev || "") + " [Products: JSON Error]");
          }
        } else {
          setDebugInfo(prev => (prev || "") + " [Products: 404]");
        }
      }

      // Handle Transactions
      if (results[1].status === 'fulfilled') {
        const res = results[1].value;
        if (res.ok) {
          try {
            const data = await res.json();
            const normalized = normalizeKeys(Array.isArray(data) ? data : []);
            setTransactions(normalized);
            if (normalized.length === 0) setDebugInfo(prev => (prev || "") + " [Transactions: Empty Array]");
          } catch (e) {
            setDebugInfo(prev => (prev || "") + " [Transactions: JSON Error]");
          }
        } else {
          setDebugInfo(prev => (prev || "") + " [Transactions: Not Found]");
        }
      }

      if (results[0].status === 'rejected' && results[1].status === 'rejected') {
        throw new Error("Gagal terhubung ke Apps Script.");
      }

    } catch (error: any) {
      setError(error.message || "Kesalahan koneksi.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setIsSyncing(true);
    setProducts(updatedProducts);
    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'UPDATE_PRODUCTS', products: updatedProducts })
      });
      return true;
    } catch (error) {
      return false;
    } finally {
      setTimeout(() => setIsSyncing(false), 1000);
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 font-medium animate-pulse">Sinkronisasi Cloud...</p>
        </div>
      );
    }

    if (error && activeTab !== AdminTab.SETTINGS) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-6">
          <div className="p-6 bg-red-50 text-red-600 rounded-3xl"><WifiOff size={48} /></div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold text-slate-900">Cloud Terputus</h3>
            <p className="text-slate-500 max-w-sm mx-auto">{error}</p>
            {debugInfo && <div className="mt-4 p-3 bg-slate-100 rounded-xl font-mono text-[10px] text-slate-500">Info: {debugInfo}</div>}
          </div>
          <div className="flex gap-3">
            <button onClick={fetchAllData} className="px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold">Refresh</button>
            <button onClick={() => setActiveTab(AdminTab.SETTINGS)} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold">Settings</button>
          </div>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard transactions={transactions} />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions transactions={transactions} onRefresh={fetchAllData} />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings onUrlUpdate={(url) => setScriptUrl(url)} />;
      default: return <Dashboard transactions={transactions} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Target size={20} /></div>
            <span className="font-bold text-xl tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {[
            { id: AdminTab.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
            { id: AdminTab.INVENTORY, icon: Package, label: 'Inventory' },
            { id: AdminTab.MAPPING, icon: Target, label: 'AI Mapping' },
            { id: AdminTab.TRANSACTIONS, icon: History, label: 'Transactions' },
          ].map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <item.icon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">{item.label}</span>}
            </button>
          ))}
          <div className="pt-4 mt-4 border-t border-slate-100">
             <button onClick={() => setActiveTab(AdminTab.SETTINGS)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${activeTab === AdminTab.SETTINGS ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <SettingsIcon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">Settings</span>}
            </button>
          </div>
        </nav>
        <div className="px-6 py-4">
          <div className={`flex items-center space-x-2 text-[10px] font-black uppercase ${error ? 'text-red-500' : 'text-green-500'}`}>
            {error ? <AlertCircle size={12} /> : <Cloud size={12} />}
            {isSidebarOpen && <span>{error ? 'Offline' : 'Cloud Active'}</span>}
          </div>
        </div>
      </aside>
      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <h2 className="font-bold text-slate-400 uppercase text-[10px] tracking-widest">Management Console</h2>
          <div className="flex items-center space-x-4">
            <button onClick={fetchAllData} className="p-2 text-slate-400 hover:bg-slate-100 rounded-full">
              <RefreshCw size={20} className={isLoading ? 'animate-spin' : ''} />
