import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Settings as SettingsIcon, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Target,
  Cloud,
  RefreshCw,
  AlertCircle,
  WifiOff
} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

const DEFAULT_URL = "https://script.google.com/macros/s/AKfycby5qNoLXSDVndwvxRDH1Qo4oI2mAuXJ7EVP7mKVdOMGVcUiBfLgyrr_z6Ad6NxF92PN4A/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [scriptUrl, setScriptUrl] = useState(() => {
    return localStorage.getItem('vision_script_url') || DEFAULT_URL;
  });

  useEffect(() => {
    fetchAllData();
  }, [scriptUrl]);

  const processRawData = (rawData: any) => {
    if (!rawData) return [];

    let data = Array.isArray(rawData) ? rawData : (rawData.data || rawData.items || []);
    if (data.length === 0) return [];

    // Jika formatnya Array of Arrays (mentah dari Sheets)
    if (Array.isArray(data[0])) {
      const headers = data[0].map((h: any) => h.toString().toLowerCase().trim());
      const rows = data.slice(1);
      return rows.map((row: any) => {
        const obj: any = {};
        headers.forEach((header: string, index: number) => {
          // Normalisasi header agar cocok dengan yang diharapkan komponen (hapus spasi)
          const key = header.replace(/ /g, ' ');
          obj[key] = row[index];
        });
        return obj;
      });
    }

    // Jika formatnya sudah Array of Objects
    return data.map((item: any) => {
      const normalized: any = {};
      Object.keys(item).forEach(key => {
        const k = key.toLowerCase().trim().replace(/_/g, ' ');
        normalized[k] = item[key];
      });
      return normalized;
    });
  };

  const fetchAllData = async () => {
    if (!scriptUrl || scriptUrl.includes('...')) {
      setIsLoading(false);
      setError("URL Apps Script belum dikonfigurasi.");
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      const results = await Promise.allSettled([
        fetch(`${scriptUrl}?action=GET_PRODUCTS`),
        fetch(`${scriptUrl}?action=GET_TRANSACTIONS`)
      ]);

      if (results[0].status === 'fulfilled' && results[0].value.ok) {
        const data = await results[0].value.json();
        setProducts(processRawData(data));
      }

      if (results[1].status === 'fulfilled' && results[1].value.ok) {
        const data = await results[1].value.json();
        const processed = processRawData(data);
        setTransactions(processed);
      }

    } catch (error: any) {
      setError("Koneksi gagal. Pastikan Apps Script Web App sudah di-deploy dengan akses 'Anyone'.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setProducts(updatedProducts);
    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'UPDATE_PRODUCTS', products: updatedProducts })
      });
      return true;
    } catch (error) {
      return false;
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-400 text-sm font-medium">Sinkronisasi Cloud...</p>
        </div>
      );
    }

    if (error && activeTab !== AdminTab.SETTINGS) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-6">
          <div className="p-6 bg-red-50 text-red-600 rounded-3xl"><WifiOff size={48} /></div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold text-slate-900">Koneksi Terputus</h3>
            <p className="text-slate-500 text-sm max-w-sm mx-auto">{error}</p>
          </div>
          <button onClick={() => setActiveTab(AdminTab.SETTINGS)} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold">Buka Settings</button>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard transactions={transactions} />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions transactions={transactions} onRefresh={fetchAllData} />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings onUrlUpdate={(url) => setScriptUrl(url)} />;
      default: return <Dashboard transactions={transactions} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Target size={20} /></div>
            <span className="font-bold text-lg tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
        <nav className="flex-1 px-4 space-y-1.5 mt-4">
          {[
            { id: AdminTab.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
            { id: AdminTab.INVENTORY, icon: Package, label: 'Inventory' },
            { id: AdminTab.MAPPING, icon: Target, label: 'AI Mapping' },
            { id: AdminTab.TRANSACTIONS, icon: History, label: 'Transactions' },
          ].map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <item.icon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">{item.label}</span>}
            </button>
          ))}
