  const [searchQuery, setSearchQuery] = useState('');

  // Normalisasi pencarian agar lebih fleksibel
  const filteredTransactions = transactions.filter(t => {
    const id = (t["id transaksi"] || t.id || '').toString().toLowerCase();
    const name = (t["nama produk"] || t.name || '').toString().toLowerCase();
    const query = searchQuery.toLowerCase();
    return id.includes(query) || name.includes(query);
  });

  const totalSales = transactions.reduce((sum, t) => sum + (Number(t.total) || 0), 0);

  const formatTime = (dateStr: any) => {
    if (!dateStr) return "-";
    try {
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return dateStr;
      return date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
      return dateStr;
    }
  };

  const formatDate = (dateStr: any) => {
    if (!dateStr) return "-";
    try {
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return "";
      return date.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
    } catch (e) {
      return "";
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
