import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  History, 
  Settings as SettingsIcon, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Target,
  Cloud,
  RefreshCw,
  AlertCircle,
  WifiOff
} from 'lucide-react';
import { AdminTab } from './types';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Transactions from './pages/Transactions';
import Settings from './pages/Settings';
import CVMonitor from './pages/CVMonitor';

// TEMPEL URL APPS SCRIPT ANDA DI SINI
const SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxC-MIdsxtbFktGhLU3Yh5dALiDeLoB1QwiFdHsXULB8aKCvgzOVVyIE12pjXePIPhDtA/exec";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AdminTab>(AdminTab.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [products, setProducts] = useState<any[]>([]);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchAllData();
  }, []);

  const processRawData = (rawData: any) => {
    if (!rawData) return [];

    let data = Array.isArray(rawData) ? rawData : (rawData.data || rawData.items || []);
    if (data.length === 0) return [];

    // Jika data datang dalam bentuk Array 2D (biasanya dari Spreadsheet)
    if (Array.isArray(data[0])) {
      const headers = data[0].map((h: any) => h.toString().toLowerCase().trim());
      const rows = data.slice(1);
      return rows.map((row: any) => {
        const obj: any = {};
        headers.forEach((header: string, index: number) => {
          // Normalisasi key agar seragam (contoh: "id transaksi", "tanggal", "nama produk")
          const key = header;
          obj[key] = row[index];
        });
        return obj;
      });
    }

    // Jika data datang dalam bentuk Array of Objects
    return data.map((item: any) => {
      const normalized: any = {};
      Object.keys(item).forEach(key => {
        const k = key.toLowerCase().trim().replace(/_/g, ' ');
        normalized[k] = item[key];
      });
      return normalized;
    });
  };

  const fetchAllData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const results = await Promise.allSettled([
        fetch(`${SCRIPT_URL}?action=GET_PRODUCTS`),
        fetch(`${SCRIPT_URL}?action=GET_TRANSACTIONS`)
      ]);

      if (results[0].status === 'fulfilled' && results[0].value.ok) {
        const data = await results[0].value.json();
        setProducts(processRawData(data));
      }

      if (results[1].status === 'fulfilled' && results[1].value.ok) {
        const data = await results[1].value.json();
        setTransactions(processRawData(data));
      }

    } catch (error: any) {
      setError("Koneksi gagal. Periksa koneksi internet.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateProducts = async (updatedProducts: any[]) => {
    setProducts(updatedProducts);
    try {
      await fetch(SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'UPDATE_PRODUCTS', products: updatedProducts })
      });
      return true;
    } catch (error) {
      return false;
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-400 text-sm font-medium">Sinkronisasi Cloud...</p>
        </div>
      );
    }

    if (error && activeTab !== AdminTab.SETTINGS) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-6">
          <div className="p-6 bg-red-50 text-red-600 rounded-3xl"><WifiOff size={48} /></div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold text-slate-900">Koneksi Terputus</h3>
            <p className="text-slate-500 text-sm max-w-sm mx-auto">{error}</p>
          </div>
          <button onClick={fetchAllData} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 mx-auto">
            <RefreshCw size={18} /> Coba Lagi
          </button>
        </div>
      );
    }

    switch (activeTab) {
      case AdminTab.DASHBOARD: return <Dashboard transactions={transactions} />;
      case AdminTab.INVENTORY: return <Inventory products={products} onSync={handleUpdateProducts} />;
      case AdminTab.TRANSACTIONS: return <Transactions transactions={transactions} onRefresh={fetchAllData} />;
      case AdminTab.MAPPING: return <CVMonitor products={products} onSync={handleUpdateProducts} />;
      case AdminTab.SETTINGS: return <Settings />;
      default: return <Dashboard transactions={transactions} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <aside className={`bg-white border-r border-slate-100 transition-all duration-300 z-50 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className={`flex items-center space-x-3 ${!isSidebarOpen && 'hidden'}`}>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Target size={20} /></div>
            <span className="font-bold text-lg tracking-tight">Vision<span className="text-blue-600">Admin</span></span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
        <nav className="flex-1 px-4 space-y-1.5 mt-4">
          {[
            { id: AdminTab.DASHBOARD, icon: LayoutDashboard, label: 'Dashboard' },
            { id: AdminTab.INVENTORY, icon: Package, label: 'Inventory' },
            { id: AdminTab.MAPPING, icon: Target, label: 'AI Mapping' },
            { id: AdminTab.TRANSACTIONS, icon: History, label: 'Transactions' },
          ].map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <item.icon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">{item.label}</span>}
            </button>
          ))}
          <div className="pt-4 mt-4 border-t border-slate-100">
             <button onClick={() => setActiveTab(AdminTab.SETTINGS)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${activeTab === AdminTab.SETTINGS ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <SettingsIcon size={20} />
              {isSidebarOpen && <span className="font-semibold text-sm">Settings</span>}
            </button>
          </div>
        </nav>
        <div className="px-6 py-4">
          <div className={`flex items-center space-x-2 text-[10px] font-black uppercase ${error ? 'text-red-500' : 'text-green-500'}`}>
            {error ? <AlertCircle size={12} /> : <Cloud size={12} />}
            {isSidebarOpen && <span>{error ? 'Offline' : 'Cloud Sync'}</span>}
          </div>
        </div>
      </aside>
      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <h2 className="font-bold text-slate-400 uppercase text-[10px] tracking-widest">Enterprise Console</h2>
          <div className="flex items-center space-x-4">
            <button onClick={fetchAllData} className="p-2 text-slate-400 hover:bg-slate-100 rounded-full">
              <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} />
            </button>
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white text-xs font-bold">A</div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-8">{renderContent()}</div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, Download, QrCode, RefreshCw } from 'lucide-react';

interface TransactionsProps {
  transactions: any[];
  onRefresh: () => void;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, onRefresh }) => {
  const [searchQuery, setSearchQuery] = useState('');

  const filteredTransactions = transactions.filter(t => {
    const id = (t["id transaksi"] || t.id || '').toString().toLowerCase();
    const name = (t["nama produk"] || t.name || '').toString().toLowerCase();
    const query = searchQuery.toLowerCase();
    return id.includes(query) || name.includes(query);
  });

  const totalSales = transactions.reduce((sum, t) => sum + (Number(t.total) || 0), 0);

  const formatTime = (dateValue: any) => {
    if (!dateValue || dateValue === "" || dateValue === "-") return "-";
    try {
      const date = new Date(dateValue);
      if (isNaN(date.getTime())) return "-";
      return date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
      return "-";
    }
  };

  const formatDate = (dateValue: any) => {
    if (!dateValue || dateValue === "" || dateValue === "-") return "";
    try {
      const date = new Date(dateValue);
      if (isNaN(date.getTime())) return "";
      return date.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
    } catch (e) {
      return "";
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Transaction History</h1>
          <p className="text-slate-500 text-sm">Rekam transaksi real-time dari Google Sheets.</p>
        </div>
        <div className="flex items-center space-x-2">
          <button onClick={onRefresh} className="p-2 bg-white border border-slate-200 rounded-xl text-slate-400 hover:bg-slate-50 transition-colors">
            <RefreshCw size={18} />
          </button>
          <button className="flex items-center space-x-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-medium hover:bg-blue-700 shadow-lg shadow-blue-100">
            <Download size={18} />
            <span>Export CSV</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-gradient-to-br from-blue-600 to-blue-800 p-6 rounded-3xl text-white shadow-xl relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
            <QrCode size={140} />
          </div>
          <p className="text-blue-100 text-sm font-medium opacity-80">Total Omzet</p>
          <h3 className="text-3xl font-bold mt-1">Rp {totalSales.toLocaleString()}</h3>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <p className="text-slate-500 text-sm font-medium">Jumlah Pesanan</p>
          <div className="flex items-end justify-between mt-1">
            <h3 className="text-3xl font-bold text-slate-800">
              {[...new Set(transactions.map(t => t["id transaksi"] || t.id))].length}
            </h3>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <p className="text-slate-500 text-sm font-medium">Total Baris Data</p>
          <h3 className="text-3xl font-bold text-slate-800 mt-1">{transactions.length}</h3>
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative w-full max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Cari transaksi..." 
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-none rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest px-4">
            Menampilkan {filteredTransactions.length} baris
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50/50 text-slate-500 text-[10px] font-bold uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Waktu</th>
                <th className="px-6 py-4">ID Transaksi</th>
                <th className="px-6 py-4">Nama Produk</th>
                <th className="px-6 py-4">Harga</th>
                <th className="px-6 py-4 text-center">Qty</th>
                <th className="px-6 py-4">Total</th>
                <th className="px-6 py-4">Metode</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {filteredTransactions.map((t, idx) => {
                const dateVal = t.tanggal || t.time || t.date || "-";
                return (
                  <tr key={idx} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-700">{formatTime(dateVal)}</span>
                        <span className="text-[10px] text-slate-400">{formatDate(dateVal)}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-blue-600 font-mono text-xs font-bold">{t["id transaksi"] || t.id}</td>
                    <td className="px-6 py-4 font-medium text-slate-800">{t["nama produk"] || t.name}</td>
                    <td className="px-6 py-4 text-slate-500">Rp {Number(t.harga).toLocaleString()}</td>
                    <td className="px-6 py-4 text-center font-bold text-slate-700">{t.qty}</td>
                    <td className="px-6 py-4 font-black text-slate-900">Rp {Number(t.total).toLocaleString()}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center space-x-1.5 text-blue-600 font-black text-[10px]">
                        <QrCode size={12} />
                        <span>{t["metode bayar"] || 'QRIS'}</span>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredTransactions.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-20 text-center text-slate-400">
                    Data transaksi belum tersedia atau kolom "Tanggal" di Sheet masih kosong.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

