interface TransactionsProps {
  transactions: any[];
  onRefresh: () => void;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, onRefresh }) => {
  const [searchQuery, setSearchQuery] = useState('');

  const filteredTransactions = transactions.filter(t => {
    const id = (t.id_transaksi || t.id || '').toString().toLowerCase();
    const name = (t.nama_produk || t.name || '').toString().toLowerCase();
    const query = searchQuery.toLowerCase();
    return id.includes(query) || name.includes(query);
  });

  const totalSales = transactions.reduce((sum, t) => sum + (Number(t.total) || 0), 0);

  const formatTime = (dateValue: any) => {
    if (!dateValue || dateValue === "" || dateValue === "-") return "-";
    try {
      const date = new Date(dateValue);
      if (isNaN(date.getTime())) return "-";
      return date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
      return "-";
    }
  };

  const formatDate = (dateValue: any) => {
    if (!dateValue || dateValue === "" || dateValue === "-") return "";
    try {
      const date = new Date(dateValue);
      if (isNaN(date.getTime())) return "";
      return date.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
    } catch (e) {
      return "";
    }
